--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: -
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


--
-- Name: _audit_productos_precio(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._audit_productos_precio() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.precio_base IS DISTINCT FROM NEW.precio_base THEN
    PERFORM registrar_auditoria(
      'productos',
      'UPDATE',
      NEW.id::TEXT,
      jsonb_build_object('precio_base', OLD.precio_base),
      jsonb_build_object('precio_base', NEW.precio_base)
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: _audit_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._audit_stock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM registrar_auditoria(
      'movimientos_stock',
      'INSERT',
      NEW.id::TEXT,
      NULL,
      to_jsonb(NEW)
    );
  ELSIF TG_OP = 'UPDATE' THEN
    PERFORM registrar_auditoria(
      'movimientos_stock',
      'UPDATE',
      NEW.id::TEXT,
      to_jsonb(OLD),
      to_jsonb(NEW)
    );
  ELSIF TG_OP = 'DELETE' THEN
    PERFORM registrar_auditoria(
      'movimientos_stock',
      'DELETE',
      OLD.id::TEXT,
      to_jsonb(OLD),
      NULL
    );
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: _notif_push_async(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._notif_push_async(p_empresa_id uuid, p_tipo text, p_titulo text, p_cuerpo text, p_datos jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_url TEXT;
BEGIN
  -- Leer URL desde vault (falla silenciosamente si no está configurado)
  BEGIN
    SELECT decrypted_secret INTO v_url
    FROM vault.decrypted_secrets
    WHERE name = 'NOTIF_PUSH_URL'
    LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    v_url := NULL;
  END;

  IF v_url IS NULL OR v_url = '' THEN
    RETURN; -- Sin URL configurada, no hacer nada
  END IF;

  -- Llamada HTTP asíncrona — no bloquea la transacción principal
  PERFORM net.http_post(
    url     := v_url,
    headers := '{"Content-Type":"application/json","x-trigger":"supabase"}'::jsonb,
    body    := jsonb_build_object(
      'empresa_id', p_empresa_id,
      'tipo',       p_tipo,
      'titulo',     p_titulo,
      'cuerpo',     p_cuerpo,
      'datos',      p_datos
    )::text
  );

EXCEPTION WHEN OTHERS THEN
  -- Errores de red no deben romper la transacción del pedido/stock
  NULL;
END;
$$;


--
-- Name: FUNCTION _notif_push_async(p_empresa_id uuid, p_tipo text, p_titulo text, p_cuerpo text, p_datos jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._notif_push_async(p_empresa_id uuid, p_tipo text, p_titulo text, p_cuerpo text, p_datos jsonb) IS 'Helper asíncrono para push. Requiere extensión pg_net habilitada en Supabase y secreto NOTIF_PUSH_URL en vault apuntando al endpoint /api/notif/push-interno.';


--
-- Name: _trigger_notif_nuevo_pedido(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._trigger_notif_nuevo_pedido() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
  v_cliente_nombre TEXT;
BEGIN
  -- Solo notificar cuando el estado pasa a 'pendiente' (pedido real, no borrador)
  IF NEW.estado <> 'pendiente' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.estado = 'pendiente' THEN
    RETURN NEW; -- Ya estaba pendiente, no re-notificar
  END IF;

  -- Obtener nombre del cliente
  SELECT razon_social INTO v_cliente_nombre
  FROM clientes WHERE id = NEW.cliente_id;

  PERFORM _notif_push_async(
    NEW.empresa_id,
    'nuevo_pedido',
    'Nuevo pedido recibido',
    (COALESCE(v_cliente_nombre, 'Un cliente') || ' realizó un pedido por $' ||
     to_char(COALESCE(NEW.total, 0), 'FM999G999G990')),
    jsonb_build_object(
      'pedido_id',   NEW.id,
      'cliente_id',  NEW.cliente_id,
      'total',       NEW.total,
      'link',        '/admin/pedidos'
    )
  );

  RETURN NEW;
END;
$_$;


--
-- Name: FUNCTION _trigger_notif_nuevo_pedido(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._trigger_notif_nuevo_pedido() IS 'Notifica nuevo pedido cuando estado pasa a pendiente. Solo en INSERT o primer cambio a pendiente — no re-notifica si ya estaba pendiente.';


--
-- Name: _trigger_notif_stock_critico(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._trigger_notif_stock_critico() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_producto_nombre TEXT;
  v_empresa_id      UUID;
  v_umbral          NUMERIC := 5;
  v_disponible      NUMERIC;
BEGIN
  v_disponible := NEW.cantidad - COALESCE(NEW.cantidad_reservada, 0);

  -- Solo actuar si la cantidad disponible bajó y cruzó el umbral
  IF TG_OP = 'UPDATE' THEN
    DECLARE
      v_disponible_old NUMERIC;
    BEGIN
      v_disponible_old := OLD.cantidad - COALESCE(OLD.cantidad_reservada, 0);
      -- Si ya estaba bajo o no bajó, no notificar
      IF v_disponible_old <= v_umbral OR v_disponible > v_umbral THEN
        RETURN NEW;
      END IF;
    END;
  ELSIF TG_OP = 'INSERT' THEN
    IF v_disponible > v_umbral THEN
      RETURN NEW;
    END IF;
  END IF;

  -- Obtener nombre del producto y empresa
  SELECT p.nombre, d.empresa_id
  INTO v_producto_nombre, v_empresa_id
  FROM productos p
  JOIN depositos d ON d.id = NEW.deposito_id
  WHERE p.id = NEW.producto_id;

  IF v_empresa_id IS NULL THEN RETURN NEW; END IF;

  PERFORM _notif_push_async(
    v_empresa_id,
    'stock_critico',
    'Stock crítico',
    (COALESCE(v_producto_nombre, 'Producto') || ': quedan ' ||
     to_char(v_disponible, 'FM990D99') || ' unidades disponibles'),
    jsonb_build_object(
      'producto_id',  NEW.producto_id,
      'deposito_id',  NEW.deposito_id,
      'disponible',   v_disponible,
      'link',         '/admin/stock'
    )
  );

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION _trigger_notif_stock_critico(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._trigger_notif_stock_critico() IS 'Notifica cuando stock disponible cruza hacia abajo el umbral de 5 unidades. No notifica en cada UPDATE si ya estaba bajo — solo en el cruce del umbral.';


--
-- Name: acreditar_puntos(uuid, uuid, integer, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acreditar_puntos(p_empresa_id uuid, p_cliente_id uuid, p_puntos integer, p_concepto text DEFAULT 'Acreditación manual'::text, p_ref_tipo text DEFAULT 'manual'::text, p_usuario_id uuid DEFAULT NULL::uuid, p_usuario_nombre text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_saldo_nuevo INTEGER;
BEGIN
    -- Upsert saldo
    INSERT INTO public.saldo_puntos
           (cliente_id, empresa_id, puntos_disponibles, puntos_totales, ultimo_movimiento)
    VALUES (p_cliente_id, p_empresa_id, p_puntos, p_puntos, now())
    ON CONFLICT (cliente_id, empresa_id) DO UPDATE
       SET puntos_disponibles = saldo_puntos.puntos_disponibles + p_puntos,
           puntos_totales     = saldo_puntos.puntos_totales + p_puntos,
           ultimo_movimiento  = now()
    RETURNING puntos_disponibles INTO v_saldo_nuevo;

    -- Registrar movimiento
    INSERT INTO public.movimientos_puntos
           (cliente_id, empresa_id, tipo, cantidad, motivo, referencia_id)
    VALUES (p_cliente_id, p_empresa_id, 'ganancia', p_puntos, p_concepto, NULL);

    RETURN json_build_object('ok', true, 'saldo', v_saldo_nuevo);
END;
$$;


--
-- Name: actualizar_estado_lotes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.actualizar_estado_lotes(p_empresa_id uuid) RETURNS void
    LANGUAGE sql
    AS $$
  -- Marcar vencidos
  UPDATE lotes
  SET    estado = 'vencido', updated_at = now()
  WHERE  empresa_id       = p_empresa_id
    AND  estado           = 'vigente'
    AND  fecha_vencimiento < CURRENT_DATE
    AND  cantidad         > 0;

  -- Marcar por_vencer (próximos 7 días)
  UPDATE lotes
  SET    estado = 'por_vencer', updated_at = now()
  WHERE  empresa_id       = p_empresa_id
    AND  estado           = 'vigente'
    AND  fecha_vencimiento BETWEEN CURRENT_DATE AND (CURRENT_DATE + INTERVAL '7 days')
    AND  cantidad         > 0;

  -- Marcar agotados
  UPDATE lotes
  SET    estado = 'agotado', updated_at = now()
  WHERE  empresa_id = p_empresa_id
    AND  estado NOT IN ('agotado', 'dado_de_baja')
    AND  cantidad   = 0;
$$;


--
-- Name: ajustar_stock(uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ajustar_stock(p_producto_id uuid, p_deposito_id uuid, p_delta numeric, p_motivo text DEFAULT 'ajuste_manual'::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_empresa_id  UUID;
  v_stock_nuevo NUMERIC;
BEGIN
  -- Obtener empresa_id del depósito
  SELECT empresa_id INTO v_empresa_id
  FROM public.depositos
  WHERE id = p_deposito_id;

  IF v_empresa_id IS NULL THEN
    RETURN json_build_object('ok', false, 'error', 'Depósito no encontrado');
  END IF;

  -- Verificar autorización (debe ser admin o dueño de la empresa)
  IF NOT (
    get_rol_usuario() IN ('admin', 'dueno') AND get_empresa_id() = v_empresa_id
  ) THEN
    RETURN json_build_object('ok', false, 'error', 'Sin autorización');
  END IF;

  -- Upsert en stock
  INSERT INTO public.stock (producto_id, deposito_id, cantidad)
  VALUES (p_producto_id, p_deposito_id, GREATEST(0, p_delta))
  ON CONFLICT (producto_id, deposito_id)
  DO UPDATE SET
    cantidad   = GREATEST(0, public.stock.cantidad + p_delta),
    updated_at = NOW()
  RETURNING cantidad INTO v_stock_nuevo;

  -- Registrar en movimientos_stock
  INSERT INTO public.movimientos_stock
    (producto_id, deposito_id, tipo, cantidad, notas, usuario_id, created_at)
  VALUES (
    p_producto_id,
    p_deposito_id,
    CASE WHEN p_delta >= 0 THEN 'entrada' ELSE 'salida' END,
    ABS(p_delta),
    p_motivo,
    auth.uid(),
    NOW()
  );

  RETURN json_build_object(
    'ok',         true,
    'stock_nuevo', COALESCE(v_stock_nuevo, 0),
    'delta',       p_delta
  );

EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('ok', false, 'error', SQLERRM);
END;
$$;


--
-- Name: FUNCTION ajustar_stock(p_producto_id uuid, p_deposito_id uuid, p_delta numeric, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ajustar_stock(p_producto_id uuid, p_deposito_id uuid, p_delta numeric, p_motivo text) IS 'Ajuste manual de stock en un depósito. Delta positivo = entrada, negativo = salida. Registra en movimientos_stock.';


--
-- Name: analizar_stock_autonomo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analizar_stock_autonomo(p_empresa_id uuid) RETURNS TABLE(producto_id uuid, nombre text, stock_actual numeric, velocidad_dia numeric, dias_restantes numeric, lead_time integer, necesita_reponer boolean, cantidad_sugerida numeric, proveedor_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  WITH ventas_30d AS (
    SELECT pi2.producto_id,
           SUM(pi2.cantidad) / 30.0 AS vel_dia
    FROM pedido_items pi2
    JOIN pedidos ped ON ped.id = pi2.pedido_id
    WHERE ped.empresa_id = p_empresa_id
      AND ped.estado IN ('entregado','despachado','confirmado')
      AND ped.fecha_pedido >= now() - INTERVAL '30 days'
    GROUP BY pi2.producto_id
  ),
  stock_actual AS (
    SELECT s.producto_id,
           SUM(s.cantidad - COALESCE(s.cantidad_reservada, 0)) AS disponible
    FROM stock s
    JOIN depositos d ON d.id = s.deposito_id
    WHERE d.empresa_id = p_empresa_id
    GROUP BY s.producto_id
  )
  SELECT
    p.id,
    p.nombre,
    COALESCE(sa.disponible, 0),
    COALESCE(v.vel_dia, 0),
    CASE WHEN COALESCE(v.vel_dia, 0) > 0
      THEN COALESCE(sa.disponible, 0) / v.vel_dia
      ELSE 999
    END,
    COALESCE(p.lead_time_dias, 7),
    (COALESCE(sa.disponible, 0) <= COALESCE(p.stock_minimo, 0)),
    GREATEST(0,
      COALESCE(p.stock_objetivo,
        COALESCE(v.vel_dia, 0) * 30, 0)
      - COALESCE(sa.disponible, 0)
    ),
    p.proveedor_id_default
  FROM productos p
  LEFT JOIN ventas_30d v  ON v.producto_id = p.id
  LEFT JOIN stock_actual sa ON sa.producto_id = p.id
  WHERE p.empresa_id = p_empresa_id
    AND p.activo = true;
END;
$$;


--
-- Name: aplicar_nota_credito_cta_cte(uuid, uuid, text, text, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aplicar_nota_credito_cta_cte(p_empresa_id uuid, p_nc_id uuid, p_nc_numero text, p_cae text DEFAULT NULL::text, p_cae_vto date DEFAULT NULL::date, p_pdf_url text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_nc notas_credito%ROWTYPE;
BEGIN
  SELECT * INTO v_nc FROM notas_credito
   WHERE id = p_nc_id AND empresa_id = p_empresa_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Nota de crédito no encontrada';
  END IF;

  -- Actualizar NC con datos AFIP
  UPDATE notas_credito
     SET numero      = p_nc_numero,
         cae         = p_cae,
         cae_vto     = p_cae_vto,
         pdf_url     = p_pdf_url,
         estado      = 'emitida',
         notas_error = NULL,
         updated_at  = now()
   WHERE id = p_nc_id;

  -- Acreditar en cta_cte
  INSERT INTO cta_cte
    (cliente_id, tipo, importe, factura_id, nro_comprobante, descripcion, fecha)
  VALUES (
    v_nc.cliente_id,
    'credito',
    v_nc.total,
    v_nc.factura_id,
    p_nc_numero,
    'NC-' || v_nc.tipo || ' ' || p_nc_numero || ' — ' || v_nc.motivo,
    now()
  );
END;
$$;


