--
-- Name: fn_audit_generic(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_audit_generic() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM registrar_auditoria(
      TG_TABLE_NAME, 'INSERT', NEW.id::UUID, NULL, to_jsonb(NEW)
    );
  ELSIF TG_OP = 'UPDATE' THEN
    IF to_jsonb(OLD) IS DISTINCT FROM to_jsonb(NEW) THEN
      PERFORM registrar_auditoria(
        TG_TABLE_NAME, 'UPDATE', NEW.id::UUID, to_jsonb(OLD), to_jsonb(NEW)
      );
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    PERFORM registrar_auditoria(
      TG_TABLE_NAME, 'DELETE', OLD.id::UUID, to_jsonb(OLD), NULL
    );
  END IF;
  RETURN COALESCE(NEW, OLD);
EXCEPTION WHEN OTHERS THEN
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: fn_cierre_financiero_entrega(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_cierre_financiero_entrega() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_pedido     RECORD;
  v_empresa_id UUID;
  v_dias_cred  INT;
BEGIN
  IF NEW.estado <> 'entregado' OR OLD.estado = 'entregado' THEN RETURN NEW; END IF;

  SELECT p.*, c.dias_credito, r.empresa_id INTO v_pedido
  FROM pedidos p
  JOIN rutas r ON r.id = NEW.ruta_id
  JOIN clientes c ON c.id = p.cliente_id
  WHERE p.id = NEW.pedido_id;

  IF NOT FOUND THEN RETURN NEW; END IF;

  v_empresa_id := v_pedido.empresa_id;
  v_dias_cred  := COALESCE(v_pedido.dias_credito, 0);

  -- Encolar facturación
  INSERT INTO cola_financiera (empresa_id, tipo, referencia_id, payload)
  VALUES (v_empresa_id, 'facturar', NEW.pedido_id,
    jsonb_build_object(
      'pedido_id',   NEW.pedido_id,
      'cliente_id',  v_pedido.cliente_id,
      'total',       v_pedido.total,
      'dias_credito', v_dias_cred,
      'vence_en',    (CURRENT_DATE + v_dias_cred)::TEXT
    ));

  -- Encolar notificación de vencimiento (si tiene crédito)
  IF v_dias_cred > 0 THEN
    INSERT INTO cola_financiera (empresa_id, tipo, referencia_id, proximo_intento, payload)
    VALUES (v_empresa_id, 'notif_vencimiento', v_pedido.cliente_id,
      now() + (v_dias_cred - 3) * INTERVAL '1 day',
      jsonb_build_object('dias_vencimiento', v_dias_cred));
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fp_lotes_default_disponible(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fp_lotes_default_disponible() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.cantidad_disponible IS NULL OR NEW.cantidad_disponible = 0 THEN
    NEW.cantidad_disponible := GREATEST(NEW.cantidad - COALESCE(NEW.cantidad_reservada, 0), 0);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fp_touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fp_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$$;


--
-- Name: generar_ofertas_liquidacion(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generar_ofertas_liquidacion(p_empresa_id uuid, p_dry_run boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reglas        RECORD;
  v_lote          RECORD;
  v_dias_rest     INT;
  v_pct           NUMERIC(5,2);
  v_precio_base   NUMERIC(12,2);
  v_precio_oferta NUMERIC(12,2);
  v_cant_disp     NUMERIC(12,3);
  v_creadas       JSONB := '[]'::JSONB;
  v_desactivadas  INT   := 0;
BEGIN
  -- 1. Obtener reglas de la empresa (o defaults si no existen)
  SELECT * INTO v_reglas FROM reglas_liquidacion WHERE empresa_id = p_empresa_id;
  IF v_reglas IS NULL THEN
    v_reglas := ROW(
      gen_random_uuid(), p_empresa_id, true,
      7, 3, 10::NUMERIC, 1, 15::NUMERIC, 0, 25::NUMERIC,
      true, NOW(), NOW()
    )::reglas_liquidacion;
  END IF;
  IF NOT v_reglas.activo THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Reglas de liquidación desactivadas para esta empresa',
      'creadas', v_creadas,
      'desactivadas', v_desactivadas
    );
  END IF;

  -- 2. Iterar lotes próximos a vencer (en estado 'activo', con cantidad > 0)
  FOR v_lote IN
    SELECT l.id, l.producto_id, l.cantidad, l.fecha_vencimiento,
           p.precio_base, EXTRACT(DAY FROM (l.fecha_vencimiento - NOW()))::INT AS dias_restantes
    FROM lotes l
    JOIN productos p ON l.producto_id = p.id
    WHERE l.empresa_id = p_empresa_id
      AND l.estado = 'activo'
      AND l.cantidad > 0
      AND l.fecha_vencimiento <= (NOW() + (v_reglas.dias_alerta || ' days')::INTERVAL)
      AND l.fecha_vencimiento > NOW()  -- excluye ya vencidos
    ORDER BY l.fecha_vencimiento ASC
  LOOP
    v_dias_rest     := v_lote.dias_restantes;
    v_precio_base   := v_lote.precio_base;
    v_cant_disp     := v_lote.cantidad;

    -- Determinar % descuento según días restantes
    IF v_dias_rest <= v_reglas.dias_nivel3 THEN
      v_pct := v_reglas.pct_nivel3;
    ELSIF v_dias_rest <= v_reglas.dias_nivel2 THEN
      v_pct := v_reglas.pct_nivel2;
    ELSE
      v_pct := v_reglas.pct_nivel1;
    END IF;

    v_precio_oferta := v_precio_base * (1 - v_pct / 100);

    -- Insertar o actualizar oferta (si ya existe, actualizarla)
    INSERT INTO ofertas_liquidacion (
      empresa_id, lote_id, producto_id, precio_oferta, descuento_pct,
      cantidad_snapshot, dias_restantes_al_crear, activa, vence_oferta_at
    ) VALUES (
      p_empresa_id, v_lote.id, v_lote.producto_id, v_precio_oferta, v_pct,
      v_cant_disp, v_dias_rest, true,
      NOW() + INTERVAL '7 days'  -- oferta válida 7 días
    )
    ON CONFLICT (lote_id, empresa_id) WHERE activa
    DO UPDATE SET
      precio_oferta = v_precio_oferta,
      descuento_pct = v_pct,
      cantidad_snapshot = v_cant_disp,
      dias_restantes_al_crear = v_dias_rest,
      updated_at = NOW();

    v_creadas := v_creadas || jsonb_build_object('lote_id', v_lote.id::TEXT, 'producto_id', v_lote.producto_id::TEXT);
  END LOOP;

  -- 3. Desactivar ofertas cuyo lote ya fue completamente agotado o su oferta venció
  UPDATE ofertas_liquidacion SET
    activa = false,
    desactivada_at = NOW(),
    razon_desactivacion = 'lote_agotado_o_oferta_vencida'
  WHERE empresa_id = p_empresa_id
    AND activa = true
    AND (
      EXISTS (SELECT 1 FROM lotes WHERE id = oferta_liquidacion.lote_id AND estado IN ('agotado', 'vencido'))
      OR vence_oferta_at < NOW()
    );

  GET DIAGNOSTICS v_desactivadas = ROW_COUNT;

  IF p_dry_run THEN
    RETURN jsonb_build_object(
      'ok', true,
      'modo', 'dry_run',
      'creadas', v_creadas,
      'desactivadas', v_desactivadas
    );
  END IF;

  -- En modo real, devolver resultado
  RETURN jsonb_build_object(
    'ok', true,
    'creadas', v_creadas,
    'desactivadas', v_desactivadas
  );
END;
$$;


--
-- Name: generar_pedidos_sugeridos(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generar_pedidos_sugeridos(p_empresa_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_ciclo    RECORD;
  v_count    INT := 0;
  v_pedido   UUID;
BEGIN
  -- Recalcular ciclos primero
  PERFORM calcular_ciclos_cliente(p_empresa_id);

  -- Generar pedidos sugeridos para ciclos que vencen en próximos 3 días
  FOR v_ciclo IN
    SELECT cc.*, c.vendedor_id
    FROM ciclos_compra cc
    JOIN clientes c ON c.id = cc.cliente_id
    WHERE cc.empresa_id = p_empresa_id
      AND cc.activo = true
      AND cc.proximo_pedido <= CURRENT_DATE + INTERVAL '3 days'
      AND NOT EXISTS (
        SELECT 1 FROM pedidos p
        WHERE p.cliente_id = cc.cliente_id
          AND p.estado = 'sugerido'
          AND p.ciclo_referencia_id = cc.id
      )
  LOOP
    -- Crear pedido sugerido
    INSERT INTO pedidos (
      empresa_id, cliente_id, vendedor_id, estado,
      generado_automatico, confianza_sugerencia, ciclo_referencia_id,
      fecha_pedido, total
    ) VALUES (
      p_empresa_id, v_ciclo.cliente_id, v_ciclo.vendedor_id, 'sugerido',
      true, v_ciclo.confianza, v_ciclo.id,
      now(), 0
    ) RETURNING id INTO v_pedido;

    -- Agregar item sugerido
    INSERT INTO pedido_items (pedido_id, producto_id, cantidad, precio_unitario)
    SELECT v_pedido, v_ciclo.producto_id, v_ciclo.cantidad_promedio,
           COALESCE(lp_detalle.precio, pr.precio_base, 0)
    FROM productos pr
    LEFT JOIN listas_precios_detalle lp_detalle
      ON lp_detalle.producto_id = pr.id
      AND lp_detalle.lista_id = (
        SELECT id FROM listas_precios
        WHERE empresa_id = p_empresa_id AND es_default = true LIMIT 1
      )
    WHERE pr.id = v_ciclo.producto_id;

    -- Actualizar total del pedido
    UPDATE pedidos SET total = (
      SELECT COALESCE(SUM(cantidad * precio_unitario), 0) FROM pedido_items WHERE pedido_id = v_pedido
    ) WHERE id = v_pedido;

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


