--
-- Name: importar_productos_lote(uuid, jsonb, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.importar_productos_lote(p_empresa_id uuid, p_filas jsonb, p_lista_precio_id uuid DEFAULT NULL::uuid, p_lista_nombre text DEFAULT NULL::text, p_deposito_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_lista_id    UUID := p_lista_precio_id;
  v_deposito_id UUID := p_deposito_id;
  v_fila        JSONB;
  v_nombre      TEXT;
  v_codigo      TEXT;
  v_precio      NUMERIC;
  v_costo       NUMERIC;
  v_iva         NUMERIC;
  v_unidad      TEXT;
  v_categoria   TEXT;
  v_cat_id      UUID;
  v_prod_id     UUID;
  v_precio_act  NUMERIC;
  v_nuevos      INT := 0;
  v_actualizados INT := 0;
  v_sin_cambio  INT := 0;
  v_errores     INT := 0;
  v_err_detalle JSONB := '[]'::JSONB;
BEGIN

  -- ── 1. Resolver lista de precios ─────────────────────────────────────────
  IF v_lista_id IS NULL AND p_lista_nombre IS NOT NULL THEN
    INSERT INTO listas_precios (empresa_id, nombre, es_default, activa)
    VALUES (p_empresa_id, p_lista_nombre, FALSE, TRUE)
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_lista_id;

    IF v_lista_id IS NULL THEN
      SELECT id INTO v_lista_id FROM listas_precios
      WHERE empresa_id = p_empresa_id AND nombre = p_lista_nombre LIMIT 1;
    END IF;
  END IF;

  IF v_lista_id IS NULL THEN
    SELECT id INTO v_lista_id FROM listas_precios
    WHERE empresa_id = p_empresa_id AND es_default = TRUE AND activa = TRUE
    LIMIT 1;
  END IF;

  -- ── 2. Resolver depósito principal ────────────────────────────────────────
  IF v_deposito_id IS NULL THEN
    SELECT id INTO v_deposito_id FROM depositos
    WHERE empresa_id = p_empresa_id AND es_principal = TRUE
    LIMIT 1;
  END IF;

  -- ── 3. Procesar cada fila ─────────────────────────────────────────────────
  FOR v_fila IN SELECT * FROM jsonb_array_elements(p_filas)
  LOOP
    BEGIN
      v_nombre    := TRIM(v_fila->>'nombre');
      v_codigo    := NULLIF(TRIM(v_fila->>'codigo'), '');
      v_precio    := COALESCE((v_fila->>'precio')::NUMERIC, 0);
      v_costo     := COALESCE((v_fila->>'costo')::NUMERIC,  0);
      v_iva       := COALESCE((v_fila->>'iva')::NUMERIC,    21);
      v_unidad    := COALESCE(NULLIF(TRIM(v_fila->>'unidad'), ''), 'unidad');
      v_categoria := NULLIF(TRIM(v_fila->>'categoria'), '');

      IF v_nombre IS NULL OR LENGTH(v_nombre) < 1 THEN
        v_errores := v_errores + 1;
        v_err_detalle := v_err_detalle || jsonb_build_object('codigo', v_codigo, 'error', 'Nombre vacío');
        CONTINUE;
      END IF;

      -- Resolver o crear categoría
      v_cat_id := NULL;
      IF v_categoria IS NOT NULL THEN
        SELECT id INTO v_cat_id FROM categorias
        WHERE empresa_id = p_empresa_id
          AND LOWER(TRIM(nombre)) = LOWER(v_categoria)
        LIMIT 1;

        IF v_cat_id IS NULL THEN
          INSERT INTO categorias (empresa_id, nombre, orden)
          VALUES (p_empresa_id, v_categoria, 0)
          ON CONFLICT DO NOTHING
          RETURNING id INTO v_cat_id;

          IF v_cat_id IS NULL THEN
            SELECT id INTO v_cat_id FROM categorias
            WHERE empresa_id = p_empresa_id AND LOWER(TRIM(nombre)) = LOWER(v_categoria)
            LIMIT 1;
          END IF;
        END IF;
      END IF;

      -- Buscar producto existente por código
      v_prod_id := NULL;
      IF v_codigo IS NOT NULL THEN
        SELECT id INTO v_prod_id FROM productos
        WHERE empresa_id = p_empresa_id AND codigo = v_codigo
        LIMIT 1;
      END IF;

      IF v_prod_id IS NOT NULL THEN
        -- Producto existe: verificar si cambió precio
        v_precio_act := NULL;
        IF v_lista_id IS NOT NULL THEN
          SELECT precio INTO v_precio_act FROM precios_items
          WHERE lista_id = v_lista_id AND producto_id = v_prod_id;
        END IF;

        IF v_precio_act IS NOT NULL AND ABS(v_precio_act - v_precio) < 0.01 THEN
          -- Sin cambio
          v_sin_cambio := v_sin_cambio + 1;
        ELSE
          -- Actualizar precio_base y reactivar si estaba inactivo
          UPDATE productos
          SET precio_base = v_precio,
              activo      = TRUE,
              categoria_id = COALESCE(v_cat_id, categoria_id)
          WHERE id = v_prod_id;

          -- Upsert en lista de precios
          IF v_lista_id IS NOT NULL AND v_precio > 0 THEN
            INSERT INTO precios_items (lista_id, producto_id, precio)
            VALUES (v_lista_id, v_prod_id, v_precio)
            ON CONFLICT (lista_id, producto_id) DO UPDATE SET precio = EXCLUDED.precio;
          END IF;

          v_actualizados := v_actualizados + 1;
        END IF;

      ELSE
        -- Producto nuevo: insertar
        INSERT INTO productos (
          empresa_id, codigo, nombre, categoria_id,
          unidad, costo, precio_base, iva, activo, permite_negativo
        )
        VALUES (
          p_empresa_id, v_codigo, v_nombre, v_cat_id,
          v_unidad, v_costo, v_precio, v_iva, TRUE, FALSE
        )
        RETURNING id INTO v_prod_id;

        -- Vincular a lista de precios
        IF v_lista_id IS NOT NULL AND v_precio > 0 THEN
          INSERT INTO precios_items (lista_id, producto_id, precio)
          VALUES (v_lista_id, v_prod_id, v_precio)
          ON CONFLICT (lista_id, producto_id) DO UPDATE SET precio = EXCLUDED.precio;
        END IF;

        -- Inicializar stock en 0
        IF v_deposito_id IS NOT NULL THEN
          INSERT INTO stock (producto_id, deposito_id, cantidad, cantidad_reservada)
          VALUES (v_prod_id, v_deposito_id, 0, 0)
          ON CONFLICT (producto_id, deposito_id) DO NOTHING;
        END IF;

        v_nuevos := v_nuevos + 1;
      END IF;

    EXCEPTION WHEN OTHERS THEN
      v_errores := v_errores + 1;
      v_err_detalle := v_err_detalle || jsonb_build_object(
        'codigo', v_codigo,
        'nombre', v_nombre,
        'error',  SQLERRM
      );
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'ok',             TRUE,
    'lista_precio_id', v_lista_id,
    'resumen', jsonb_build_object(
      'nuevos',       v_nuevos,
      'actualizados', v_actualizados,
      'sin_cambio',   v_sin_cambio,
      'errores',      v_errores
    ),
    'errores_detalle', v_err_detalle
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'ok',    FALSE,
    'error', SQLERRM
  );
END;
$$;


--
-- Name: incrementar_stock_reservado(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.incrementar_stock_reservado(p_producto_id uuid, p_deposito_id uuid, p_cantidad numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_disponible NUMERIC;
BEGIN
  SELECT (cantidad - cantidad_reservada)
    INTO v_disponible
    FROM stock
   WHERE producto_id = p_producto_id
     AND deposito_id = p_deposito_id
   FOR UPDATE;

  IF v_disponible IS NULL THEN
    RAISE EXCEPTION 'No existe registro de stock para este producto/depósito';
  END IF;

  IF p_cantidad > v_disponible THEN
    RAISE EXCEPTION 'Stock insuficiente: disponible=%, solicitado=%', v_disponible, p_cantidad;
  END IF;

  UPDATE stock
     SET cantidad_reservada = cantidad_reservada + p_cantidad
   WHERE producto_id = p_producto_id
     AND deposito_id = p_deposito_id;
END;
$$;


--
-- Name: liberar_stock_reservado(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.liberar_stock_reservado(p_producto_id uuid, p_deposito_id uuid, p_cantidad numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  UPDATE stock
     SET cantidad_reservada = GREATEST(0, cantidad_reservada - p_cantidad)
   WHERE producto_id = p_producto_id
     AND deposito_id = p_deposito_id;
END;
$$;


--
-- Name: limpiar_refresh_tokens_expirados(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.limpiar_refresh_tokens_expirados() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    DELETE FROM public.refresh_tokens
    WHERE expires_at < NOW()
       OR (revocado = TRUE AND created_at < NOW() - INTERVAL '30 days');
END;
$$;


--
-- Name: marcar_preparado(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marcar_preparado(p_pedido_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_pedido RECORD;
BEGIN
  SELECT * INTO v_pedido
    FROM pedidos
   WHERE id = p_pedido_id
     AND empresa_id = get_empresa_id()
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN json_build_object('ok', false, 'error', 'Pedido no encontrado');
  END IF;

  IF v_pedido.estado <> 'confirmado' THEN
    RETURN json_build_object(
      'ok', false,
      'error', 'El pedido debe estar confirmado para pasar a preparando (estado: ' || v_pedido.estado || ')'
    );
  END IF;

  UPDATE pedidos SET estado = 'preparando' WHERE id = p_pedido_id;

  RETURN json_build_object('ok', true);

EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('ok', false, 'error', SQLERRM);
END;
$$;


--
-- Name: marcar_preparado(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marcar_preparado(p_pedido_id uuid, p_usuario_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  UPDATE public.pedidos SET estado = 'preparando' WHERE id = p_pedido_id;
  RETURN json_build_object('ok', true, 'pedido_id', p_pedido_id);
EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('ok', false, 'error', SQLERRM);
END; $$;


--
-- Name: marcar_presupuestos_expirados(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marcar_presupuestos_expirados(p_empresa_id uuid) RETURNS void
    LANGUAGE sql
    AS $$
  UPDATE presupuestos
  SET    estado = 'expirado', updated_at = now()
  WHERE  empresa_id        = p_empresa_id
    AND  estado            = 'enviado'
    AND  fecha_vencimiento < now();
$$;


--
-- Name: obtener_suscriptores_push(text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obtener_suscriptores_push(p_portal text DEFAULT NULL::text, p_usuario_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(subscription_id bigint, usuario_id uuid, endpoint text, p256dh text, auth_key text, portal text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT id, usuario_id, endpoint, p256dh, auth_key, portal
    FROM public.push_subscriptions
    WHERE activo = TRUE
      AND (p_portal IS NULL       OR portal     = p_portal)
      AND (p_usuario_ids IS NULL  OR usuario_id = ANY(p_usuario_ids));
$$;


--
-- Name: recepcionar_orden_compra(uuid, uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recepcionar_orden_compra(p_empresa_id uuid, p_orden_id uuid, p_items jsonb, p_usuario_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_item          JSONB;
  v_prod_id       UUID;
  v_cant_recib    NUMERIC;
  v_costo         NUMERIC;
  v_deposito_id   UUID;
  v_stock_actual  NUMERIC;
  v_costo_actual  NUMERIC;
  v_nuevo_costo   NUMERIC;
  v_total_cant    NUMERIC;
  v_procesados    INT := 0;
  v_pendiente     NUMERIC;
  v_total_recibida NUMERIC;
  v_total_cant_oc  NUMERIC;
BEGIN
  -- Validar que la OC pertenece a la empresa
  IF NOT EXISTS (
    SELECT 1 FROM ordenes_compra WHERE id = p_orden_id AND empresa_id = p_empresa_id
  ) THEN
    RAISE EXCEPTION 'Orden de compra no encontrada';
  END IF;

  -- Depósito principal de la empresa (es_principal=true, fallback al primero por id)
  SELECT d.id INTO v_deposito_id
    FROM depositos d
   WHERE d.empresa_id = p_empresa_id
   ORDER BY d.es_principal DESC, d.id ASC
   LIMIT 1;

  IF v_deposito_id IS NULL THEN
    RAISE EXCEPTION 'La empresa no tiene depósitos configurados';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_prod_id    := (v_item->>'producto_id')::UUID;
    v_cant_recib := (v_item->>'cantidad_recibida')::NUMERIC;
    v_costo      := (v_item->>'precio_costo')::NUMERIC;

    IF v_cant_recib <= 0 THEN CONTINUE; END IF;

    -- Obtener stock actual y costo promedio
    SELECT cantidad, costo_promedio INTO v_stock_actual, v_costo_actual
      FROM stock
     WHERE producto_id = v_prod_id AND deposito_id = v_deposito_id
       FOR UPDATE;

    IF NOT FOUND THEN
      -- Crear registro de stock si no existe
      INSERT INTO stock (producto_id, deposito_id, cantidad, costo_promedio)
      VALUES (v_prod_id, v_deposito_id, 0, 0)
      ON CONFLICT (producto_id, deposito_id) DO NOTHING;

      v_stock_actual := 0;
      v_costo_actual := 0;
    END IF;

    -- Costo promedio ponderado
    v_total_cant := v_stock_actual + v_cant_recib;
    IF v_total_cant > 0 THEN
      v_nuevo_costo := (v_stock_actual * v_costo_actual + v_cant_recib * v_costo) / v_total_cant;
    ELSE
      v_nuevo_costo := v_costo;
    END IF;

    -- Actualizar stock
    UPDATE stock
       SET cantidad       = v_stock_actual + v_cant_recib,
           costo_promedio = v_nuevo_costo,
           updated_at     = now()
     WHERE producto_id = v_prod_id AND deposito_id = v_deposito_id;

    -- Actualizar costo en productos también
    UPDATE productos
       SET costo = v_nuevo_costo
     WHERE id = v_prod_id;

    -- Movimiento de stock
    INSERT INTO movimientos_stock
      (producto_id, deposito_id, tipo, cantidad, costo_unitario, referencia, usuario_id, created_at)
    VALUES
      (v_prod_id, v_deposito_id, 'entrada_compra', v_cant_recib, v_costo,
       'OC:' || p_orden_id, p_usuario_id, now());

    -- Actualizar cantidad_recibida en el ítem de la OC
    UPDATE ordenes_compra_items
       SET cantidad_recibida = cantidad_recibida + v_cant_recib,
           precio_costo      = v_costo
     WHERE orden_compra_id = p_orden_id AND producto_id = v_prod_id;

    v_procesados := v_procesados + 1;
  END LOOP;

  -- Actualizar estado de la OC
  SELECT
    SUM(cantidad)         INTO v_total_cant_oc
  FROM ordenes_compra_items WHERE orden_compra_id = p_orden_id;

  SELECT
    SUM(cantidad_recibida) INTO v_total_recibida
  FROM ordenes_compra_items WHERE orden_compra_id = p_orden_id;

  UPDATE ordenes_compra
     SET estado     = CASE
                        WHEN v_total_recibida >= v_total_cant_oc THEN 'recibida'
                        WHEN v_total_recibida > 0               THEN 'recibida_parcial'
                        ELSE estado
                      END,
         updated_at = now()
   WHERE id = p_orden_id;

  RETURN jsonb_build_object('items_procesados', v_procesados);
END;
$$;


--
-- Name: registrar_auditoria(text, text, text, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_auditoria(p_tabla text, p_accion text, p_registro_id text, p_datos_antes jsonb DEFAULT NULL::jsonb, p_datos_despues jsonb DEFAULT NULL::jsonb, p_ip text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO audit_log (
    empresa_id,
    usuario_id,
    tabla,
    accion,
    registro_id,
    datos_antes,
    datos_despues,
    ip
  ) VALUES (
    get_empresa_id(),
    auth.uid(),
    p_tabla,
    p_accion,
    p_registro_id,
    p_datos_antes,
    p_datos_despues,
    p_ip
  );
END;
$$;


--
-- Name: registrar_cobro(uuid, uuid, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_cobro(p_empresa_id uuid, p_cliente_id uuid, p_monto numeric, p_medio text, p_referencia text DEFAULT NULL::text, p_notas text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_cobro_id UUID;
  v_nro      TEXT;
BEGIN
  -- Número de comprobante secuencial por empresa
  SELECT 'COB-' || LPAD(COALESCE(MAX(CAST(regexp_replace(nro_comprobante,'[^0-9]','','g') AS INT)),0)::TEXT,'6','0')
  INTO   v_nro
  FROM   cobros
  WHERE  empresa_id = p_empresa_id;

  INSERT INTO cobros (empresa_id, cliente_id, monto, medio, referencia, notas)
  VALUES (p_empresa_id, p_cliente_id, p_monto, p_medio, p_referencia, p_notas)
  RETURNING id INTO v_cobro_id;

  INSERT INTO cta_cte
    (empresa_id, cliente_id, tipo, importe, cobro_id, nro_comprobante, descripcion, medio_pago)
  VALUES
    (p_empresa_id, p_cliente_id, 'cobro', p_monto, v_cobro_id, v_nro,
     'Cobro ' || p_medio || COALESCE(' — ' || p_referencia, ''), p_medio);

  RETURN json_build_object('ok', true, 'cobro_id', v_cobro_id);
END;
$$;


--
-- Name: registrar_cobro_completo(uuid, uuid, numeric, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_cobro_completo(p_empresa_id uuid, p_cliente_id uuid, p_monto numeric, p_medio text, p_referencia text DEFAULT NULL::text, p_notas text DEFAULT NULL::text, p_usuario_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_cobro_id      UUID;
  v_nro           TEXT;
BEGIN
  -- Validaciones básicas
  IF p_monto <= 0 THEN
    RETURN json_build_object('ok', false, 'error', 'El monto debe ser mayor a cero');
  END IF;

  -- Verificar que el cliente pertenece a la empresa
  IF NOT EXISTS (
    SELECT 1 FROM clientes WHERE id = p_cliente_id AND empresa_id = p_empresa_id
  ) THEN
    RETURN json_build_object('ok', false, 'error', 'Cliente no encontrado en la empresa');
  END IF;

  -- Generar número de recibo secuencial
  v_nro := siguiente_numero_comprobante(p_empresa_id, 'cobro');

  -- Insertar cobro
  INSERT INTO cobros (empresa_id, cliente_id, monto, medio, referencia, notas, usuario_id)
  VALUES (p_empresa_id, p_cliente_id, p_monto, p_medio, p_referencia, p_notas,
          COALESCE(p_usuario_id, auth.uid()))
  RETURNING id INTO v_cobro_id;

  -- Insertar movimiento en cuenta corriente (crédito)
  INSERT INTO cta_cte
    (cliente_id, tipo, importe, cobro_id, nro_comprobante, descripcion, medio_pago)
  VALUES
    (p_cliente_id, 'cobro', p_monto, v_cobro_id, v_nro,
     'Cobro ' || p_medio || COALESCE(' — ' || p_referencia, ''), p_medio);

  RETURN json_build_object(
    'ok',      true,
    'cobro_id', v_cobro_id,
    'nro',     v_nro
  );

EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('ok', false, 'error', SQLERRM);
END;
$$;


--
-- Name: registrar_movimiento_cta_cte(uuid, uuid, text, numeric, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_movimiento_cta_cte(p_empresa_id uuid, p_cliente_id uuid, p_tipo text, p_importe numeric, p_descripcion text DEFAULT NULL::text, p_fecha timestamp with time zone DEFAULT now()) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_cta_id UUID;
  v_nro    TEXT;
BEGIN
  SELECT 'MOV-' || LPAD(COALESCE(MAX(CAST(regexp_replace(nro_comprobante,'[^0-9]','','g') AS INT)),0)::TEXT,'6','0')
  INTO   v_nro
  FROM   cta_cte
  WHERE  empresa_id = p_empresa_id;

  INSERT INTO cta_cte
    (empresa_id, cliente_id, tipo, importe, nro_comprobante, descripcion, fecha)
  VALUES
    (p_empresa_id, p_cliente_id, p_tipo, p_importe, v_nro,
     COALESCE(p_descripcion, 'Nota de ' || replace(p_tipo, '_', ' ')), p_fecha)
  RETURNING id INTO v_cta_id;

  RETURN json_build_object('ok', true, 'cta_cte_id', v_cta_id);
END;
$$;


--
-- Name: registrar_movimiento_puntos(uuid, uuid, character varying, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_movimiento_puntos(p_cliente_id uuid, p_empresa_id uuid, p_tipo character varying, p_cantidad numeric, p_motivo text DEFAULT NULL::text, p_referencia_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE v_movimiento_id UUID;
BEGIN
  INSERT INTO movimientos_puntos (cliente_id, empresa_id, tipo, cantidad, motivo, referencia_id)
  VALUES (p_cliente_id, p_empresa_id, p_tipo, p_cantidad, p_motivo, p_referencia_id)
  RETURNING id INTO v_movimiento_id;
  UPDATE saldo_puntos SET
    puntos_disponibles = CASE WHEN p_tipo = 'ganancia' THEN puntos_disponibles + p_cantidad WHEN p_tipo = 'canje' THEN puntos_disponibles - p_cantidad ELSE puntos_disponibles END,
    puntos_canjeados = CASE WHEN p_tipo = 'canje' THEN puntos_canjeados + p_cantidad ELSE puntos_canjeados END,
    puntos_totales = puntos_totales + CASE WHEN p_tipo = 'ganancia' THEN p_cantidad WHEN p_tipo = 'canje' THEN -p_cantidad ELSE 0 END,
    ultimo_movimiento = NOW()
  WHERE cliente_id = p_cliente_id AND empresa_id = p_empresa_id;
  RETURN v_movimiento_id;
END;
$$;


--
-- Name: registrar_pago_proveedor(uuid, uuid, uuid, numeric, text, date, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_pago_proveedor(p_empresa_id uuid, p_proveedor_id uuid, p_factura_id uuid, p_monto numeric, p_medio text DEFAULT 'transferencia'::text, p_fecha date DEFAULT CURRENT_DATE, p_referencia text DEFAULT NULL::text, p_notas text DEFAULT NULL::text, p_usuario_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_factura      record;
  v_nuevo_pagado numeric;
  v_nuevo_estado text;
BEGIN
  -- Leer factura y validar empresa
  SELECT * INTO v_factura
  FROM public.facturas_proveedor
  WHERE id = p_factura_id AND empresa_id = p_empresa_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Factura no encontrada');
  END IF;

  IF v_factura.estado = 'anulada' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La factura está anulada');
  END IF;

  IF v_factura.estado = 'pagada' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La factura ya está pagada');
  END IF;

  -- Insertar pago
  INSERT INTO public.pagos_proveedor (
    empresa_id, proveedor_id, factura_id,
    monto, medio_pago, fecha_pago, referencia, notas, usuario_id
  ) VALUES (
    p_empresa_id, p_proveedor_id, p_factura_id,
    p_monto, p_medio, p_fecha, p_referencia, p_notas, p_usuario_id
  );

  -- Actualizar total_pagado y estado
  v_nuevo_pagado := LEAST(v_factura.total_pagado + p_monto, v_factura.total);

  v_nuevo_estado := CASE
    WHEN v_nuevo_pagado >= v_factura.total THEN 'pagada'
    WHEN v_nuevo_pagado > 0               THEN 'parcial'
    ELSE 'pendiente'
  END;

  UPDATE public.facturas_proveedor
  SET total_pagado = v_nuevo_pagado,
      estado       = v_nuevo_estado,
      updated_at   = now()
  WHERE id = p_factura_id;

  RETURN jsonb_build_object(
    'ok',           true,
    'total_pagado', v_nuevo_pagado,
    'saldo',        v_factura.total - v_nuevo_pagado,
    'estado',       v_nuevo_estado
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
END;
$$;


--
-- Name: reservar_remito_nro(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reservar_remito_nro(p_empresa_id uuid, p_pedido_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_existente INT;
  v_nuevo     INT;
BEGIN
  -- Si ya tiene número, devolverlo
  SELECT remito_nro INTO v_existente
    FROM pedidos WHERE id = p_pedido_id AND empresa_id = p_empresa_id;

  IF v_existente IS NOT NULL THEN
    RETURN v_existente;
  END IF;

  -- Bloqueo pesimista: obtener y reservar el siguiente número
  INSERT INTO contadores_empresa (empresa_id, tipo, ultimo_numero, prefijo)
  VALUES (p_empresa_id, 'REMITO', 0, '')
  ON CONFLICT (empresa_id, tipo) DO NOTHING;

  UPDATE contadores_empresa
     SET ultimo_numero = ultimo_numero + 1
   WHERE empresa_id = p_empresa_id AND tipo = 'REMITO'
  RETURNING ultimo_numero INTO v_nuevo;

  UPDATE pedidos SET remito_nro = v_nuevo
   WHERE id = p_pedido_id AND empresa_id = p_empresa_id;

  RETURN v_nuevo;
END;
$$;


--
-- Name: rpc_crear_pedido(uuid, uuid, uuid, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_crear_pedido(p_cliente_id uuid, p_chofer_id uuid, p_usuario_id uuid, p_items jsonb, p_observaciones text DEFAULT NULL::text, p_canal text DEFAULT 'web'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_pedido_id     UUID;
    v_numero        TEXT;
    v_total         NUMERIC(14,2) := 0;
    v_item          JSONB;
    v_producto_id   UUID;
    v_cantidad      NUMERIC(10,3);
    v_precio        NUMERIC(14,2);
    v_subtotal      NUMERIC(14,2);
    v_restante      NUMERIC(10,3);
    v_lote          RECORD;
    v_items_insert  JSONB[]  := '{}';
    v_lotes_usados  UUID[] := '{}';
    v_stock_row     RECORD;
BEGIN

    -- ── 1. Lock optimista por cliente ─────────────────────────────────────────
    -- Usar advisory lock basado en cliente_id evita bloquear la tabla completa.
    -- pg_try_advisory_xact_lock devuelve FALSE si otro proceso ya tiene el lock
    -- para este cliente → falla rápido en lugar de esperar indefinidamente.
    IF NOT pg_try_advisory_xact_lock(hashtext('pedido_cliente_' || p_cliente_id::text)) THEN
        RAISE EXCEPTION 'PEDIDO_CONCURRENTE'
            USING ERRCODE = 'P0001',
                  HINT    = 'El cliente ya tiene un pedido en proceso. Reintentá en unos segundos.';
    END IF;

    -- ── 2. Validar cliente activo ────────────────────────────────────────────
    IF NOT EXISTS (SELECT 1 FROM public.clientes WHERE id = p_cliente_id AND activo = TRUE) THEN
        RAISE EXCEPTION 'CLIENTE_INACTIVO'
            USING ERRCODE = 'P0002',
                  HINT    = 'El cliente no existe o está inactivo.';
    END IF;

    -- ── 3. Validar que p_items no esté vacío ─────────────────────────────────
    IF jsonb_array_length(p_items) = 0 THEN
        RAISE EXCEPTION 'PEDIDO_SIN_ITEMS'
            USING ERRCODE = 'P0003',
                  HINT    = 'El pedido debe tener al menos un ítem.';
    END IF;

    -- ── 4. Generar número de pedido (secuencial + año) ───────────────────────
    SELECT 'PED-' || TO_CHAR(NOW(), 'YYYY') || '-' || LPAD(nextval('seq_pedidos')::text, 6, '0')
    INTO v_numero;

    -- ── 5. Crear cabecera del pedido ─────────────────────────────────────────
    INSERT INTO public.pedidos (
        numero_pedido, cliente_id, chofer_id, usuario_id,
        estado, canal, observaciones, total, fecha_pedido
    )
    VALUES (
        v_numero, p_cliente_id, p_chofer_id, p_usuario_id,
        'pendiente', p_canal, p_observaciones, 0, NOW()
    )
    RETURNING id INTO v_pedido_id;

    -- ── 6. Procesar ítems: descuento FIFO de lotes + cálculo de total ────────
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP

        v_producto_id := (v_item->>'producto_id')::UUID;
        v_cantidad    := (v_item->>'cantidad')::NUMERIC;
        v_precio      := (v_item->>'precio_unitario')::NUMERIC;
        v_subtotal    := ROUND(v_cantidad * v_precio, 2);
        v_restante    := v_cantidad;

        -- Validar stock global antes de intentar descuento por lotes
        SELECT SUM(cantidad_disponible) INTO v_stock_row
        FROM public.lotes
        WHERE producto_id = v_producto_id
          AND cantidad_disponible > 0
          AND (fecha_vencimiento IS NULL OR fecha_vencimiento > CURRENT_DATE);

        IF v_stock_row IS NULL OR v_stock_row < v_cantidad THEN
            RAISE EXCEPTION 'STOCK_INSUFICIENTE'
                USING ERRCODE = 'P0004',
                      HINT    = 'Sin stock suficiente para producto ' || v_producto_id::text;
        END IF;

        -- Descontar FIFO sobre lotes: FOR UPDATE SKIP LOCKED evita deadlocks
        -- entre transacciones concurrentes que tocan el mismo producto
        FOR v_lote IN
            SELECT id, cantidad_disponible
            FROM public.lotes
            WHERE producto_id = v_producto_id
              AND cantidad_disponible > 0
              AND (fecha_vencimiento IS NULL OR fecha_vencimiento > CURRENT_DATE)
            ORDER BY fecha_vencimiento ASC NULLS LAST, id ASC
            FOR UPDATE SKIP LOCKED
        LOOP
            EXIT WHEN v_restante <= 0;

            DECLARE v_descuento NUMERIC(10,3);
            BEGIN
                v_descuento := LEAST(v_lote.cantidad_disponible, v_restante);

                -- UPDATE directo con expresión — 1 statement, no ciclo
                UPDATE public.lotes
                SET cantidad_disponible = cantidad_disponible - v_descuento,
                    updated_at          = NOW()
                WHERE id = v_lote.id;

                v_lotes_usados := array_append(v_lotes_usados, v_lote.id);
                v_restante     := v_restante - v_descuento;
            END;
        END LOOP;

        -- Si quedó restante sin cubrir (race condition entre SKIPs)
        IF v_restante > 0 THEN
            RAISE EXCEPTION 'STOCK_INSUFICIENTE_RACE'
                USING ERRCODE = 'P0004',
                      HINT    = 'Stock insuficiente tras descuento FIFO para producto ' || v_producto_id::text;
        END IF;

        -- Acumular total
        v_total := v_total + v_subtotal;

        -- Preparar row para batch insert
        v_items_insert := array_append(v_items_insert,
            jsonb_build_object(
                'pedido_id',       v_pedido_id,
                'producto_id',     v_producto_id,
                'cantidad',        v_cantidad,
                'precio_unitario', v_precio,
                'subtotal',        v_subtotal
            )
        );

    END LOOP;

    -- ── 7. Batch INSERT de items (1 statement) ────────────────────────────────
    INSERT INTO public.pedido_items (pedido_id, producto_id, cantidad, precio_unitario, subtotal)
    SELECT
        (elem->>'pedido_id')::UUID,
        (elem->>'producto_id')::UUID,
        (elem->>'cantidad')::NUMERIC,
        (elem->>'precio_unitario')::NUMERIC,
        (elem->>'subtotal')::NUMERIC
    FROM unnest(v_items_insert) AS elem;

    -- ── 8. UPDATE total del pedido (RETURNING evita SELECT adicional) ─────────
    UPDATE public.pedidos
    SET total = v_total, updated_at = NOW()
    WHERE id = v_pedido_id;

    -- ── 9. Actualizar stock agregado (1 UPDATE por producto, no por lote) ─────
    UPDATE public.stock s
    SET cantidad_disponible = (
        SELECT COALESCE(SUM(l.cantidad_disponible), 0)
        FROM public.lotes l
        WHERE l.producto_id = s.producto_id
          AND l.cantidad_disponible > 0
    ),
    updated_at = NOW()
    WHERE s.producto_id IN (
        SELECT DISTINCT (elem->>'producto_id')::UUID FROM unnest(v_items_insert) AS elem
    );

    -- ── 10. Actualizar saldo cuenta corriente del cliente ──────────────────────
    UPDATE public.clientes
    SET saldo_cuenta_corriente = saldo_cuenta_corriente + v_total,
        updated_at             = NOW()
    WHERE id = p_cliente_id;

    -- ── 11. Registrar en audit_log ─────────────────────────────────────────────
    INSERT INTO public.audit_log (tabla, registro_id, accion, usuario_id, datos_despues)
    VALUES ('pedidos', v_pedido_id, 'INSERT', p_usuario_id,
            jsonb_build_object('numero', v_numero, 'total', v_total, 'canal', p_canal));

    -- ── 12. Retornar resultado tipado ──────────────────────────────────────────
    RETURN jsonb_build_object(
        'ok',         TRUE,
        'pedido_id',  v_pedido_id,
        'numero',     v_numero,
        'total',      v_total,
        'estado',     'pendiente'
    );

EXCEPTION
    WHEN OTHERS THEN
        -- Re-lanzar con contexto adicional para logging en la API
        RAISE EXCEPTION '%', SQLERRM
            USING ERRCODE = SQLSTATE,
                  HINT    = 'rpc_crear_pedido falló para cliente ' || p_cliente_id::text;
END;
$$;


--
-- Name: FUNCTION rpc_crear_pedido(p_cliente_id uuid, p_chofer_id uuid, p_usuario_id uuid, p_items jsonb, p_observaciones text, p_canal text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_crear_pedido(p_cliente_id uuid, p_chofer_id uuid, p_usuario_id uuid, p_items jsonb, p_observaciones text, p_canal text) IS 'Crea un pedido con descuento FIFO de lotes. Usa advisory lock por cliente y SKIP LOCKED para eliminar lock contention.';


--
-- Name: set_notif_prefs_auto_updated(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_notif_prefs_auto_updated() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN NEW.updated_at = NOW(); RETURN NEW; END;
$$;


--
-- Name: siguiente_numero_comprobante(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.siguiente_numero_comprobante(p_empresa_id uuid, p_tipo text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_nuevo  INT;
  v_prefijo TEXT;
BEGIN
  -- INSERT ... ON CONFLICT garantiza que la fila exista
  INSERT INTO contadores_empresa (empresa_id, tipo, ultimo_numero, prefijo)
  VALUES (p_empresa_id, p_tipo, 0, '')
  ON CONFLICT (empresa_id, tipo) DO NOTHING;

  -- Bloqueo pesimista: nadie más puede incrementar hasta que terminemos
  SELECT ultimo_numero + 1, prefijo
    INTO v_nuevo, v_prefijo
    FROM contadores_empresa
   WHERE empresa_id = p_empresa_id AND tipo = p_tipo
   FOR UPDATE;

  UPDATE contadores_empresa
     SET ultimo_numero = v_nuevo
   WHERE empresa_id = p_empresa_id AND tipo = p_tipo;

  -- Formato: prefijo + número con ceros a la izquierda (8 dígitos)
  RETURN v_prefijo || LPAD(v_nuevo::TEXT, 8, '0');
END;
$$;


--
-- Name: sync_factura_vencimiento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_factura_vencimiento() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Siempre mantener ambas columnas sincronizadas
  IF NEW.fecha_vencimiento IS DISTINCT FROM OLD.fecha_vencimiento THEN
    NEW.vencimiento := NEW.fecha_vencimiento;
  END IF;
  IF NEW.vencimiento IS DISTINCT FROM OLD.vencimiento THEN
    NEW.fecha_vencimiento := NEW.vencimiento;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: tg_score_cobro(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_score_cobro() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  PERFORM calcular_score_cliente(NEW.cliente_id, NEW.empresa_id, 'pago_registrado');
  RETURN NEW;
END;
$$;


--
-- Name: tg_score_entrega(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_score_entrega() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_cli UUID;
  v_emp UUID;
BEGIN
  IF NEW.estado = 'entregado' AND OLD.estado <> 'entregado' THEN
    SELECT p.cliente_id, r.empresa_id INTO v_cli, v_emp
    FROM pedidos p
    JOIN rutas r ON r.id = NEW.ruta_id
    WHERE p.id = NEW.pedido_id;
    IF FOUND THEN
      PERFORM calcular_score_cliente(v_cli, v_emp, 'entrega_confirmada');
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trigger_crear_saldo_puntos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_crear_saldo_puntos() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.empresa_id IS NOT NULL THEN
    INSERT INTO saldo_puntos (cliente_id, empresa_id, puntos_disponibles, puntos_canjeados, puntos_totales)
    VALUES (NEW.id, NEW.empresa_id, 0, 0, 0)
    ON CONFLICT (empresa_id, cliente_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trigger_force_empresa_id_etapa7(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_force_empresa_id_etapa7() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN NEW.empresa_id := get_empresa_id(); RETURN NEW; END;
$$;


--
-- Name: trigger_notif_pedido_estado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_notif_pedido_estado() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    -- Solo notificar si el estado realmente cambió
    IF OLD.estado IS DISTINCT FROM NEW.estado THEN
        PERFORM pg_notify(
            'pedido_estado_cambio',
            jsonb_build_object(
                'pedido_id',  NEW.id,
                'numero',     NEW.numero_pedido,
                'cliente_id', NEW.cliente_id,
                'chofer_id',  NEW.chofer_id,
                'estado_old', OLD.estado,
                'estado_new', NEW.estado,
                'ts',         EXTRACT(EPOCH FROM NOW())::BIGINT
            )::text
        );
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: apply_rls(jsonb, integer); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.apply_rls(wal jsonb, max_record_bytes integer DEFAULT (1024 * 1024)) RETURNS SETOF realtime.wal_rls
    LANGUAGE plpgsql
    AS $$
declare
    -- Regclass of the table e.g. public.notes
    entity_ regclass = (quote_ident(wal ->> 'schema') || '.' || quote_ident(wal ->> 'table'))::regclass;

    -- I, U, D, T: insert, update ...
    action realtime.action = (
        case wal ->> 'action'
            when 'I' then 'INSERT'
            when 'U' then 'UPDATE'
            when 'D' then 'DELETE'
            else 'ERROR'
        end
    );

    -- Is row level security enabled for the table
    is_rls_enabled bool = relrowsecurity from pg_class where oid = entity_;

    subscriptions realtime.subscription[] = array_agg(subs)
        from
            realtime.subscription subs
        where
            subs.entity = entity_
            -- Filter by action early - only get subscriptions interested in this action
            -- action_filter column can be: '*' (all), 'INSERT', 'UPDATE', or 'DELETE'
            and (subs.action_filter = '*' or subs.action_filter = action::text);

    -- Subscription vars
    working_role regrole;
    working_selected_columns text[];
    claimed_role regrole;
    claims jsonb;

    subscription_id uuid;
    subscription_has_access bool;
    visible_to_subscription_ids uuid[] = '{}';

    -- structured info for wal's columns
    columns realtime.wal_column[];
    -- previous identity values for update/delete
    old_columns realtime.wal_column[];

    error_record_exceeds_max_size boolean = octet_length(wal::text) > max_record_bytes;

    -- Primary jsonb output for record
    output jsonb;

    -- Loop record for iterating unique roles (outer loop)
    role_record record;
    -- Loop record for iterating unique selected_columns within a role (inner loop)
    cols_record record;
    -- Subscription ids visible at the role level (before fanning out by selected_columns)
    visible_role_sub_ids uuid[] = '{}';

begin
    perform set_config('role', null, true);

    columns =
        array_agg(
            (
                x->>'name',
                x->>'type',
                x->>'typeoid',
                realtime.cast(
                    (x->'value') #>> '{}',
                    coalesce(
                        (x->>'typeoid')::regtype, -- null when wal2json version <= 2.4
                        (x->>'type')::regtype
                    )
                ),
                (pks ->> 'name') is not null,
                true
            )::realtime.wal_column
        )
        from
            jsonb_array_elements(wal -> 'columns') x
            left join jsonb_array_elements(wal -> 'pk') pks
                on (x ->> 'name') = (pks ->> 'name');

    old_columns =
        array_agg(
            (
                x->>'name',
                x->>'type',
                x->>'typeoid',
                realtime.cast(
                    (x->'value') #>> '{}',
                    coalesce(
                        (x->>'typeoid')::regtype, -- null when wal2json version <= 2.4
                        (x->>'type')::regtype
                    )
                ),
                (pks ->> 'name') is not null,
                true
            )::realtime.wal_column
        )
        from
            jsonb_array_elements(wal -> 'identity') x
            left join jsonb_array_elements(wal -> 'pk') pks
                on (x ->> 'name') = (pks ->> 'name');

    for role_record in
        select claims_role
        from (select distinct claims_role from unnest(subscriptions)) t
        order by claims_role::text
    loop
        working_role := role_record.claims_role;

        -- Update `is_selectable` for columns and old_columns (once per role)
        columns =
            array_agg(
                (
                    c.name,
                    c.type_name,
                    c.type_oid,
                    c.value,
                    c.is_pkey,
                    pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')
                )::realtime.wal_column
            )
            from
                unnest(columns) c;

        old_columns =
                array_agg(
                    (
                        c.name,
                        c.type_name,
                        c.type_oid,
                        c.value,
                        c.is_pkey,
                        pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')
                    )::realtime.wal_column
                )
                from
                    unnest(old_columns) c;

        if action <> 'DELETE' and count(1) = 0 from unnest(columns) c where c.is_pkey then
            -- Fan out 400 error per distinct selected_columns for this role
            for cols_record in
                select selected_columns
                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t
                order by coalesce(array_to_string(selected_columns, ','), '')
            loop
                working_selected_columns := cols_record.selected_columns;
                return next (
                    jsonb_build_object(
                        'schema', wal ->> 'schema',
                        'table', wal ->> 'table',
                        'type', action
                    ),
                    is_rls_enabled,
                    (select array_agg(s.subscription_id) from unnest(subscriptions) as s where s.claims_role = working_role and (s.selected_columns is not distinct from working_selected_columns)),
                    array['Error 400: Bad Request, no primary key']
                )::realtime.wal_rls;
            end loop;

        -- The claims role does not have SELECT permission to the primary key of entity
        elsif action <> 'DELETE' and sum(c.is_selectable::int) <> count(1) from unnest(columns) c where c.is_pkey then
            -- Fan out 401 error per distinct selected_columns for this role
            for cols_record in
                select selected_columns
                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t
                order by coalesce(array_to_string(selected_columns, ','), '')
            loop
                working_selected_columns := cols_record.selected_columns;
                return next (
                    jsonb_build_object(
                        'schema', wal ->> 'schema',
                        'table', wal ->> 'table',
                        'type', action
                    ),
                    is_rls_enabled,
                    (select array_agg(s.subscription_id) from unnest(subscriptions) as s where s.claims_role = working_role and (s.selected_columns is not distinct from working_selected_columns)),
                    array['Error 401: Unauthorized']
                )::realtime.wal_rls;
            end loop;

        else
            -- Create the prepared statement (once per role)
            if is_rls_enabled and action <> 'DELETE' then
                if (select 1 from pg_prepared_statements where name = 'walrus_rls_stmt' limit 1) > 0 then
                    deallocate walrus_rls_stmt;
                end if;
                execute realtime.build_prepared_statement_sql('walrus_rls_stmt', entity_, columns);
            end if;

            -- Collect all visible subscription IDs for this role (filter check + RLS check)
            visible_role_sub_ids = '{}';

            for subscription_id, claims in (
                    select
                        subs.subscription_id,
                        subs.claims
                    from
                        unnest(subscriptions) subs
                    where
                        subs.entity = entity_
                        and subs.claims_role = working_role
                        and (
                            realtime.is_visible_through_filters(columns, subs.filters)
                            or (
                              action = 'DELETE'
                              and realtime.is_visible_through_filters(old_columns, subs.filters)
                            )
                        )
            ) loop

                if not is_rls_enabled or action = 'DELETE' then
                    visible_role_sub_ids = visible_role_sub_ids || subscription_id;
                else
                    -- Check if RLS allows the role to see the record
                    perform
                        -- Trim leading and trailing quotes from working_role because set_config
                        -- doesn't recognize the role as valid if they are included
                        set_config('role', trim(both '"' from working_role::text), true),
                        set_config('request.jwt.claims', claims::text, true);

                    execute 'execute walrus_rls_stmt' into subscription_has_access;

                    if subscription_has_access then
                        visible_role_sub_ids = visible_role_sub_ids || subscription_id;
                    end if;
                end if;
            end loop;

            perform set_config('role', null, true);

            -- Inner loop: per distinct selected_columns for this role
            for cols_record in
                select selected_columns
                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t
                order by coalesce(array_to_string(selected_columns, ','), '')
            loop
                working_selected_columns := cols_record.selected_columns;

                output = jsonb_build_object(
                    'schema', wal ->> 'schema',
                    'table', wal ->> 'table',
                    'type', action,
                    'commit_timestamp', to_char(
                        ((wal ->> 'timestamp')::timestamptz at time zone 'utc'),
                        'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
                    ),
                    'columns', (
                        select
                            jsonb_agg(
                                jsonb_build_object(
                                    'name', pa.attname,
                                    'type', pt.typname
                                )
                                order by pa.attnum asc
                            )
                        from
                            pg_attribute pa
                            join pg_type pt
                                on pa.atttypid = pt.oid
                            left join (
                                select unnest(conkey) as pkey_attnum
                                from pg_constraint
                                where conrelid = entity_ and contype = 'p'
                            ) pk on pk.pkey_attnum = pa.attnum
                        where
                            attrelid = entity_
                            and attnum > 0
                            and pg_catalog.has_column_privilege(working_role, entity_, pa.attname, 'SELECT')
                            and (working_selected_columns is null or pa.attname = any(working_selected_columns) or pk.pkey_attnum is not null)
                    )
                )
                -- Add "record" key for insert and update
                || case
                    when action in ('INSERT', 'UPDATE') then
                        jsonb_build_object(
                            'record',
                            (
                                select
                                    jsonb_object_agg(
                                        -- if unchanged toast, get column name and value from old record
                                        coalesce((c).name, (oc).name),
                                        case
                                            when (c).name is null then (oc).value
                                            else (c).value
                                        end
                                    )
                                from
                                    unnest(columns) c
                                    full outer join unnest(old_columns) oc
                                        on (c).name = (oc).name
                                where
                                    coalesce((c).is_selectable, (oc).is_selectable)
                                    and (working_selected_columns is null or coalesce((c).name, (oc).name) = any(working_selected_columns) or coalesce((c).is_pkey, (oc).is_pkey))
                                    and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                            )
                        )
                    else '{}'::jsonb
                end
                -- Add "old_record" key for update and delete
                || case
                    when action = 'UPDATE' then
                        jsonb_build_object(
                                'old_record',
                                (
                                    select jsonb_object_agg((c).name, (c).value)
                                    from unnest(old_columns) c
                                    where
                                        (c).is_selectable
                                        and (working_selected_columns is null or (c).name = any(working_selected_columns) or (c).is_pkey)
                                        and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                                )
                            )
                    when action = 'DELETE' then
                        jsonb_build_object(
                            'old_record',
                            (
                                select jsonb_object_agg((c).name, (c).value)
                                from unnest(old_columns) c
                                where
                                    (c).is_selectable
                                    and (working_selected_columns is null or (c).name = any(working_selected_columns) or (c).is_pkey)
                                    and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                                    and ( not is_rls_enabled or (c).is_pkey ) -- if RLS enabled, we can't secure deletes so filter to pkey
                            )
                        )
                    else '{}'::jsonb
                end;

                -- Filter visible_role_sub_ids to those matching the current selected_columns group
                visible_to_subscription_ids = coalesce(
                    (
                        select array_agg(s.subscription_id)
                        from unnest(subscriptions) s
                        where s.claims_role = working_role
                          and (s.selected_columns is not distinct from working_selected_columns)
                          and s.subscription_id = any(visible_role_sub_ids)
                    ),
                    '{}'::uuid[]
                );

                return next (
                    output,
                    is_rls_enabled,
                    visible_to_subscription_ids,
                    case
                        when error_record_exceeds_max_size then array['Error 413: Payload Too Large']
                        else '{}'
                    end
                )::realtime.wal_rls;
            end loop;

        end if;
    end loop;

    perform set_config('role', null, true);
end;
$$;


--
-- Name: broadcast_changes(text, text, text, text, text, record, record, text); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.broadcast_changes(topic_name text, event_name text, operation text, table_name text, table_schema text, new record, old record, level text DEFAULT 'ROW'::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Declare a variable to hold the JSONB representation of the row
    row_data jsonb := '{}'::jsonb;
BEGIN
    IF level = 'STATEMENT' THEN
        RAISE EXCEPTION 'function can only be triggered for each row, not for each statement';
    END IF;
    -- Check the operation type and handle accordingly
    IF operation = 'INSERT' OR operation = 'UPDATE' OR operation = 'DELETE' THEN
        row_data := jsonb_build_object('old_record', OLD, 'record', NEW, 'operation', operation, 'table', table_name, 'schema', table_schema);
        PERFORM realtime.send (row_data, event_name, topic_name);
    ELSE
        RAISE EXCEPTION 'Unexpected operation type: %', operation;
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to process the row: %', SQLERRM;
END;

$$;


--
-- Name: build_prepared_statement_sql(text, regclass, realtime.wal_column[]); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.build_prepared_statement_sql(prepared_statement_name text, entity regclass, columns realtime.wal_column[]) RETURNS text
    LANGUAGE sql
    AS $$
      /*
      Builds a sql string that, if executed, creates a prepared statement to
      tests retrive a row from *entity* by its primary key columns.
      Example
          select realtime.build_prepared_statement_sql('public.notes', '{"id"}'::text[], '{"bigint"}'::text[])
      */
          select
      'prepare ' || prepared_statement_name || ' as
          select
              exists(
                  select
                      1
                  from
                      ' || entity || '
                  where
                      ' || string_agg(quote_ident(pkc.name) || '=' || quote_nullable(pkc.value #>> '{}') , ' and ') || '
              )'
          from
              unnest(columns) pkc
          where
              pkc.is_pkey
          group by
              entity
      $$;


--
-- Name: cast(text, regtype); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime."cast"(val text, type_ regtype) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
  res jsonb;
begin
  if type_::text = 'bytea' then
    return to_jsonb(val);
  end if;
  execute format('select to_jsonb(%L::'|| type_::text || ')', val) into res;
  return res;
end
$$;


--
-- Name: check_equality_op(realtime.equality_op, regtype, text, text); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.check_equality_op(op realtime.equality_op, type_ regtype, val_1 text, val_2 text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
      /*
      Casts *val_1* and *val_2* as type *type_* and check the *op* condition for truthiness
      */
      declare
          op_symbol text = (
              case
                  when op = 'eq' then '='
                  when op = 'neq' then '!='
                  when op = 'lt' then '<'
                  when op = 'lte' then '<='
                  when op = 'gt' then '>'
                  when op = 'gte' then '>='
                  when op = 'in' then '= any'
                  else 'UNKNOWN OP'
              end
          );
          res boolean;
      begin
          execute format(
              'select %L::'|| type_::text || ' ' || op_symbol
              || ' ( %L::'
              || (
                  case
                      when op = 'in' then type_::text || '[]'
                      else type_::text end
              )
              || ')', val_1, val_2) into res;
          return res;
      end;
      $$;


--
-- Name: is_visible_through_filters(realtime.wal_column[], realtime.user_defined_filter[]); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.is_visible_through_filters(columns realtime.wal_column[], filters realtime.user_defined_filter[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
    /*
    Should the record be visible (true) or filtered out (false) after *filters* are applied
    */
        select
            -- Default to allowed when no filters present
            $2 is null -- no filters. this should not happen because subscriptions has a default
            or array_length($2, 1) is null -- array length of an empty array is null
            or bool_and(
                coalesce(
                    realtime.check_equality_op(
                        op:=f.op,
                        type_:=coalesce(
                            col.type_oid::regtype, -- null when wal2json version <= 2.4
                            col.type_name::regtype
                        ),
                        -- cast jsonb to text
                        val_1:=col.value #>> '{}',
                        val_2:=f.value
                    ),
                    false -- if null, filter does not match
                )
            )
        from
            unnest(filters) f
            join unnest(columns) col
                on f.column_name = col.name;
    $_$;


--
-- Name: list_changes(name, name, integer, integer); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.list_changes(publication name, slot_name name, max_changes integer, max_record_bytes integer) RETURNS TABLE(wal jsonb, is_rls_enabled boolean, subscription_ids uuid[], errors text[], slot_changes_count bigint)
    LANGUAGE sql
    SET log_min_messages TO 'fatal'
    AS $$
  WITH pub AS (
    SELECT
      concat_ws(
        ',',
        CASE WHEN bool_or(pubinsert) THEN 'insert' ELSE NULL END,
        CASE WHEN bool_or(pubupdate) THEN 'update' ELSE NULL END,
        CASE WHEN bool_or(pubdelete) THEN 'delete' ELSE NULL END
      ) AS w2j_actions,
      coalesce(
        string_agg(
          realtime.quote_wal2json(format('%I.%I', schemaname, tablename)::regclass),
          ','
        ) filter (WHERE ppt.tablename IS NOT NULL),
        ''
      ) AS w2j_add_tables
    FROM pg_publication pp
    LEFT JOIN pg_publication_tables ppt ON pp.pubname = ppt.pubname
    WHERE pp.pubname = publication
    GROUP BY pp.pubname
    LIMIT 1
  ),
  -- MATERIALIZED ensures pg_logical_slot_get_changes is called exactly once
  w2j AS MATERIALIZED (
    SELECT x.*, pub.w2j_add_tables
    FROM pub,
         pg_logical_slot_get_changes(
           slot_name, null, max_changes,
           'include-pk', 'true',
           'include-transaction', 'false',
           'include-timestamp', 'true',
           'include-type-oids', 'true',
           'format-version', '2',
           'actions', pub.w2j_actions,
           'add-tables', pub.w2j_add_tables
         ) x
  ),
  slot_count AS (
    SELECT count(*)::bigint AS cnt
    FROM w2j
    WHERE w2j.w2j_add_tables <> ''
  ),
  rls_filtered AS (
    SELECT xyz.wal, xyz.is_rls_enabled, xyz.subscription_ids, xyz.errors
    FROM w2j,
         realtime.apply_rls(
           wal := w2j.data::jsonb,
           max_record_bytes := max_record_bytes
         ) xyz(wal, is_rls_enabled, subscription_ids, errors)
    WHERE w2j.w2j_add_tables <> ''
      AND xyz.subscription_ids[1] IS NOT NULL
  )
  SELECT rf.wal, rf.is_rls_enabled, rf.subscription_ids, rf.errors, sc.cnt
  FROM rls_filtered rf, slot_count sc

  UNION ALL

  SELECT null, null, null, null, sc.cnt
  FROM slot_count sc
  WHERE NOT EXISTS (SELECT 1 FROM rls_filtered)
$$;


--
-- Name: quote_wal2json(regclass); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.quote_wal2json(entity regclass) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  SELECT
    realtime.wal2json_escape_identifier(nsp.nspname::text)
    || '.'
    || realtime.wal2json_escape_identifier(pc.relname::text)
  FROM pg_class pc
  JOIN pg_namespace nsp ON pc.relnamespace = nsp.oid
  WHERE pc.oid = entity
$$;


--
-- Name: send(jsonb, text, text, boolean); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.send(payload jsonb, event text, topic text, private boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  generated_id uuid;
  final_payload jsonb;
BEGIN
  BEGIN
    generated_id := gen_random_uuid();

    -- Check if payload has an 'id' key, if not, add the generated UUID
    IF payload ? 'id' THEN
      final_payload := payload;
    ELSE
      final_payload := jsonb_set(payload, '{id}', to_jsonb(generated_id));
    END IF;

    -- Set the topic configuration
    EXECUTE format('SET LOCAL realtime.topic TO %L', topic);

    INSERT INTO realtime.messages (id, payload, event, topic, private, extension)
    VALUES (generated_id, final_payload, event, topic, private, 'broadcast');
  EXCEPTION
    WHEN OTHERS THEN
      RAISE WARNING 'WarnSendingBroadcastMessage: %', SQLERRM;
  END;
END;
$$;


--
-- Name: send_binary(bytea, text, text, boolean); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.send_binary(payload bytea, event text, topic text, private boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  generated_id uuid;
BEGIN
  BEGIN
    generated_id := gen_random_uuid();

    EXECUTE format('SET LOCAL realtime.topic TO %L', topic);

    INSERT INTO realtime.messages (id, binary_payload, event, topic, private, extension)
    VALUES (generated_id, payload, event, topic, private, 'broadcast');
  EXCEPTION
    WHEN OTHERS THEN
      RAISE WARNING 'WarnSendingBroadcastMessage: %', SQLERRM;
  END;
END;
$$;


--
-- Name: subscription_check_filters(); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.subscription_check_filters() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
    col_names text[] = coalesce(
            array_agg(a.attname order by a.attnum),
            '{}'::text[]
        )
        from
            pg_catalog.pg_attribute a
        where
            a.attrelid = new.entity
            and a.attnum > 0
            and not a.attisdropped
            and pg_catalog.has_column_privilege(
                (new.claims ->> 'role'),
                a.attrelid,
                a.attnum,
                'SELECT'
            );
    filter realtime.user_defined_filter;
    col_type regtype;
    in_val jsonb;
    selected_col text;
begin
    for filter in select * from unnest(new.filters) loop
        if not filter.column_name = any(col_names) then
            raise exception 'invalid column for filter %', filter.column_name;
        end if;

        col_type = (
            select atttypid::regtype
            from pg_catalog.pg_attribute
            where attrelid = new.entity
                  and attname = filter.column_name
        );
        if col_type is null then
            raise exception 'failed to lookup type for column %', filter.column_name;
        end if;

        if filter.op = 'in'::realtime.equality_op then
            in_val = realtime.cast(filter.value, (col_type::text || '[]')::regtype);
            if coalesce(jsonb_array_length(in_val), 0) > 100 then
                raise exception 'too many values for `in` filter. Maximum 100';
            end if;
        else
            perform realtime.cast(filter.value, col_type);
        end if;
    end loop;

    if new.selected_columns is not null then
        for selected_col in select * from unnest(new.selected_columns) loop
            if not selected_col = any(col_names) then
                raise exception 'invalid column for select %', selected_col;
            end if;
        end loop;
    end if;

    new.filters = coalesce(
        array_agg(f order by f.column_name, f.op, f.value),
        '{}'
    ) from unnest(new.filters) f;

    new.selected_columns = (
        select array_agg(c order by c)
        from unnest(new.selected_columns) c
    );

    return new;
end;
$$;


--
-- Name: to_regrole(text); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.to_regrole(role_name text) RETURNS regrole
    LANGUAGE sql IMMUTABLE
    AS $$ select role_name::regrole $$;


--
-- Name: topic(); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.topic() RETURNS text
    LANGUAGE sql STABLE
    AS $$
select nullif(current_setting('realtime.topic', true), '')::text;
$$;


--
-- Name: wal2json_escape_identifier(text); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.wal2json_escape_identifier(name text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  -- Prefix `\`, `,`, `.`, and any whitespace with `\`
  SELECT regexp_replace(name, '([\\,.[:space:]])', '\\\1', 'g')
$$;


--
-- Name: allow_any_operation(text[]); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.allow_any_operation(expected_operations text[]) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  WITH current_operation AS (
    SELECT storage.operation() AS raw_operation
  ),
  normalized AS (
    SELECT CASE
      WHEN raw_operation LIKE 'storage.%' THEN substr(raw_operation, 9)
      ELSE raw_operation
    END AS current_operation
    FROM current_operation
  )
  SELECT EXISTS (
    SELECT 1
    FROM normalized n
    CROSS JOIN LATERAL unnest(expected_operations) AS expected_operation
    WHERE expected_operation IS NOT NULL
      AND expected_operation <> ''
      AND n.current_operation = CASE
        WHEN expected_operation LIKE 'storage.%' THEN substr(expected_operation, 9)
        ELSE expected_operation
      END
  );
$$;


--
-- Name: allow_only_operation(text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.allow_only_operation(expected_operation text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  WITH current_operation AS (
    SELECT storage.operation() AS raw_operation
  ),
  normalized AS (
    SELECT
      CASE
        WHEN raw_operation LIKE 'storage.%' THEN substr(raw_operation, 9)
        ELSE raw_operation
      END AS current_operation,
      CASE
        WHEN expected_operation LIKE 'storage.%' THEN substr(expected_operation, 9)
        ELSE expected_operation
      END AS requested_operation
    FROM current_operation
  )
  SELECT CASE
    WHEN requested_operation IS NULL OR requested_operation = '' THEN FALSE
    ELSE COALESCE(current_operation = requested_operation, FALSE)
  END
  FROM normalized;
$$;


--
-- Name: can_insert_object(text, text, uuid, jsonb); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.can_insert_object(bucketid text, name text, owner uuid, metadata jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO "storage"."objects" ("bucket_id", "name", "owner", "metadata") VALUES (bucketid, name, owner, metadata);
  -- hack to rollback the successful insert
  RAISE sqlstate 'PT200' using
  message = 'ROLLBACK',
  detail = 'rollback successful insert';
END
$$;


--
-- Name: enforce_bucket_name_length(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.enforce_bucket_name_length() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
    if length(new.name) > 100 then
        raise exception 'bucket name "%" is too long (% characters). Max is 100.', new.name, length(new.name);
    end if;
    return new;
end;
$$;


--
-- Name: extension(text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.extension(name text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    _parts text[];
    _filename text;
BEGIN
    -- Split on "/" to get path segments
    SELECT string_to_array(name, '/') INTO _parts;
    -- Get the last path segment (the actual filename)
    SELECT _parts[array_length(_parts, 1)] INTO _filename;
    -- Extract extension: reverse, split on '.', then reverse again
    RETURN reverse(split_part(reverse(_filename), '.', 1));
END
$$;


--
-- Name: filename(text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.filename(name text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
_parts text[];
BEGIN
	select string_to_array(name, '/') into _parts;
	return _parts[array_length(_parts,1)];
END
$$;


--
-- Name: foldername(text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.foldername(name text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    _parts text[];
BEGIN
    -- Split on "/" to get path segments
    SELECT string_to_array(name, '/') INTO _parts;
    -- Return everything except the last segment
    RETURN _parts[1 : array_length(_parts,1) - 1];
END
$$;


--
-- Name: get_common_prefix(text, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.get_common_prefix(p_key text, p_prefix text, p_delimiter text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
SELECT CASE
    WHEN position(p_delimiter IN substring(p_key FROM length(p_prefix) + 1)) > 0
    THEN left(p_key, length(p_prefix) + position(p_delimiter IN substring(p_key FROM length(p_prefix) + 1)))
    ELSE NULL
END;
$$;


--
-- Name: get_size_by_bucket(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.get_size_by_bucket() RETURNS TABLE(size bigint, bucket_id text)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    return query
        select sum((metadata->>'size')::bigint)::bigint as size, obj.bucket_id
        from "storage".objects as obj
        group by obj.bucket_id;
END
$$;


--
-- Name: list_multipart_uploads_with_delimiter(text, text, text, integer, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.list_multipart_uploads_with_delimiter(bucket_id text, prefix_param text, delimiter_param text, max_keys integer DEFAULT 100, next_key_token text DEFAULT ''::text, next_upload_token text DEFAULT ''::text) RETURNS TABLE(key text, id text, created_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $_$
BEGIN
    RETURN QUERY EXECUTE
        'SELECT DISTINCT ON(key COLLATE "C") * from (
            SELECT
                CASE
                    WHEN position($2 IN substring(key from length($1) + 1)) > 0 THEN
                        substring(key from 1 for length($1) + position($2 IN substring(key from length($1) + 1)))
                    ELSE
                        key
                END AS key, id, created_at
            FROM
                storage.s3_multipart_uploads
            WHERE
                bucket_id = $5 AND
                key ILIKE $1 || ''%'' AND
                CASE
                    WHEN $4 != '''' AND $6 = '''' THEN
                        CASE
                            WHEN position($2 IN substring(key from length($1) + 1)) > 0 THEN
                                substring(key from 1 for length($1) + position($2 IN substring(key from length($1) + 1))) COLLATE "C" > $4
                            ELSE
                                key COLLATE "C" > $4
                            END
                    ELSE
                        true
                END AND
                CASE
                    WHEN $6 != '''' THEN
                        id COLLATE "C" > $6
                    ELSE
                        true
                    END
            ORDER BY
                key COLLATE "C" ASC, created_at ASC) as e order by key COLLATE "C" LIMIT $3'
        USING prefix_param, delimiter_param, max_keys, next_key_token, bucket_id, next_upload_token;
END;
$_$;


--
-- Name: list_objects_with_delimiter(text, text, text, integer, text, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.list_objects_with_delimiter(_bucket_id text, prefix_param text, delimiter_param text, max_keys integer DEFAULT 100, start_after text DEFAULT ''::text, next_token text DEFAULT ''::text, sort_order text DEFAULT 'asc'::text) RETURNS TABLE(name text, id uuid, metadata jsonb, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
    v_peek_name TEXT;
    v_current RECORD;
    v_common_prefix TEXT;

    -- Configuration
    v_is_asc BOOLEAN;
    v_prefix TEXT;
    v_start TEXT;
    v_upper_bound TEXT;
    v_file_batch_size INT;

    -- Seek state
    v_next_seek TEXT;
    v_count INT := 0;

    -- Dynamic SQL for batch query only
    v_batch_query TEXT;

BEGIN
    -- ========================================================================
    -- INITIALIZATION
    -- ========================================================================
    v_is_asc := lower(coalesce(sort_order, 'asc')) = 'asc';
    v_prefix := coalesce(prefix_param, '');
    v_start := CASE WHEN coalesce(next_token, '') <> '' THEN next_token ELSE coalesce(start_after, '') END;
    v_file_batch_size := LEAST(GREATEST(max_keys * 2, 100), 1000);

    -- Calculate upper bound for prefix filtering (bytewise, using COLLATE "C")
    IF v_prefix = '' THEN
        v_upper_bound := NULL;
    ELSIF right(v_prefix, 1) = delimiter_param THEN
        v_upper_bound := left(v_prefix, -1) || chr(ascii(delimiter_param) + 1);
    ELSE
        v_upper_bound := left(v_prefix, -1) || chr(ascii(right(v_prefix, 1)) + 1);
    END IF;

    -- Build batch query (dynamic SQL - called infrequently, amortized over many rows)
    IF v_is_asc THEN
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND o.name COLLATE "C" >= $2 ' ||
                'AND o.name COLLATE "C" < $3 ORDER BY o.name COLLATE "C" ASC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND o.name COLLATE "C" >= $2 ' ||
                'ORDER BY o.name COLLATE "C" ASC LIMIT $4';
        END IF;
    ELSE
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND o.name COLLATE "C" < $2 ' ||
                'AND o.name COLLATE "C" >= $3 ORDER BY o.name COLLATE "C" DESC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND o.name COLLATE "C" < $2 ' ||
                'ORDER BY o.name COLLATE "C" DESC LIMIT $4';
        END IF;
    END IF;

    -- ========================================================================
    -- SEEK INITIALIZATION: Determine starting position
    -- ========================================================================
    IF v_start = '' THEN
        IF v_is_asc THEN
            v_next_seek := v_prefix;
        ELSE
            -- DESC without cursor: find the last item in range
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_next_seek FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" >= v_prefix AND o.name COLLATE "C" < v_upper_bound
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            ELSIF v_prefix <> '' THEN
                SELECT o.name INTO v_next_seek FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" >= v_prefix
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            ELSE
                SELECT o.name INTO v_next_seek FROM storage.objects o
                WHERE o.bucket_id = _bucket_id
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            END IF;

            IF v_next_seek IS NOT NULL THEN
                v_next_seek := v_next_seek || delimiter_param;
            ELSE
                RETURN;
            END IF;
        END IF;
    ELSE
        -- Cursor provided: determine if it refers to a folder or leaf
        IF EXISTS (
            SELECT 1 FROM storage.objects o
            WHERE o.bucket_id = _bucket_id
              AND o.name COLLATE "C" LIKE v_start || delimiter_param || '%'
            LIMIT 1
        ) THEN
            -- Cursor refers to a folder
            IF v_is_asc THEN
                v_next_seek := v_start || chr(ascii(delimiter_param) + 1);
            ELSE
                v_next_seek := v_start || delimiter_param;
            END IF;
        ELSE
            -- Cursor refers to a leaf object
            IF v_is_asc THEN
                v_next_seek := v_start || delimiter_param;
            ELSE
                v_next_seek := v_start;
            END IF;
        END IF;
    END IF;

    -- ========================================================================
    -- MAIN LOOP: Hybrid peek-then-batch algorithm
    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch
    -- ========================================================================
    LOOP
        EXIT WHEN v_count >= max_keys;

        -- STEP 1: PEEK using STATIC SQL (plan cached, very fast)
        IF v_is_asc THEN
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" >= v_next_seek AND o.name COLLATE "C" < v_upper_bound
                ORDER BY o.name COLLATE "C" ASC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" >= v_next_seek
                ORDER BY o.name COLLATE "C" ASC LIMIT 1;
            END IF;
        ELSE
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" < v_next_seek AND o.name COLLATE "C" >= v_prefix
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            ELSIF v_prefix <> '' THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" < v_next_seek AND o.name COLLATE "C" >= v_prefix
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" < v_next_seek
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            END IF;
        END IF;

        EXIT WHEN v_peek_name IS NULL;

        -- STEP 2: Check if this is a FOLDER or FILE
        v_common_prefix := storage.get_common_prefix(v_peek_name, v_prefix, delimiter_param);

        IF v_common_prefix IS NOT NULL THEN
            -- FOLDER: Emit and skip to next folder (no heap access needed)
            name := rtrim(v_common_prefix, delimiter_param);
            id := NULL;
            updated_at := NULL;
            created_at := NULL;
            last_accessed_at := NULL;
            metadata := NULL;
            RETURN NEXT;
            v_count := v_count + 1;

            -- Advance seek past the folder range
            IF v_is_asc THEN
                v_next_seek := left(v_common_prefix, -1) || chr(ascii(delimiter_param) + 1);
            ELSE
                v_next_seek := v_common_prefix;
            END IF;
        ELSE
            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)
            -- For ASC: upper_bound is the exclusive upper limit (< condition)
            -- For DESC: prefix is the inclusive lower limit (>= condition)
            FOR v_current IN EXECUTE v_batch_query USING _bucket_id, v_next_seek,
                CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix) ELSE v_prefix END, v_file_batch_size
            LOOP
                v_common_prefix := storage.get_common_prefix(v_current.name, v_prefix, delimiter_param);

                IF v_common_prefix IS NOT NULL THEN
                    -- Hit a folder: exit batch, let peek handle it
                    v_next_seek := v_current.name;
                    EXIT;
                END IF;

                -- Emit file
                name := v_current.name;
                id := v_current.id;
                updated_at := v_current.updated_at;
                created_at := v_current.created_at;
                last_accessed_at := v_current.last_accessed_at;
                metadata := v_current.metadata;
                RETURN NEXT;
                v_count := v_count + 1;

                -- Advance seek past this file
                IF v_is_asc THEN
                    v_next_seek := v_current.name || delimiter_param;
                ELSE
                    v_next_seek := v_current.name;
                END IF;

                EXIT WHEN v_count >= max_keys;
            END LOOP;
        END IF;
    END LOOP;
END;
$_$;


--
-- Name: operation(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.operation() RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN current_setting('storage.operation', true);
END;
$$;


--
-- Name: protect_delete(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.protect_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Check if storage.allow_delete_query is set to 'true'
    IF COALESCE(current_setting('storage.allow_delete_query', true), 'false') != 'true' THEN
        RAISE EXCEPTION 'Direct deletion from storage tables is not allowed. Use the Storage API instead.'
            USING HINT = 'This prevents accidental data loss from orphaned objects.',
                  ERRCODE = '42501';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: search(text, text, integer, integer, integer, text, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.search(prefix text, bucketname text, limits integer DEFAULT 100, levels integer DEFAULT 1, offsets integer DEFAULT 0, search text DEFAULT ''::text, sortcolumn text DEFAULT 'name'::text, sortorder text DEFAULT 'asc'::text) RETURNS TABLE(name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb)
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
    v_peek_name TEXT;
    v_current RECORD;
    v_common_prefix TEXT;
    v_delimiter CONSTANT TEXT := '/';

    -- Configuration
    v_limit INT;
    v_prefix TEXT;
    v_prefix_lower TEXT;
    v_is_asc BOOLEAN;
    v_order_by TEXT;
    v_sort_order TEXT;
    v_upper_bound TEXT;
    v_file_batch_size INT;

    -- Dynamic SQL for batch query only
    v_batch_query TEXT;

    -- Seek state
    v_next_seek TEXT;
    v_count INT := 0;
    v_skipped INT := 0;
BEGIN
    -- ========================================================================
    -- INITIALIZATION
    -- ========================================================================
    v_limit := LEAST(coalesce(limits, 100), 1500);
    v_prefix := coalesce(prefix, '') || coalesce(search, '');
    v_prefix_lower := lower(v_prefix);
    v_is_asc := lower(coalesce(sortorder, 'asc')) = 'asc';
    v_file_batch_size := LEAST(GREATEST(v_limit * 2, 100), 1000);

    -- Validate sort column
    CASE lower(coalesce(sortcolumn, 'name'))
        WHEN 'name' THEN v_order_by := 'name';
        WHEN 'updated_at' THEN v_order_by := 'updated_at';
        WHEN 'created_at' THEN v_order_by := 'created_at';
        WHEN 'last_accessed_at' THEN v_order_by := 'last_accessed_at';
        ELSE v_order_by := 'name';
    END CASE;

    v_sort_order := CASE WHEN v_is_asc THEN 'asc' ELSE 'desc' END;

    -- ========================================================================
    -- NON-NAME SORTING: Use path_tokens approach (unchanged)
    -- ========================================================================
    IF v_order_by != 'name' THEN
        RETURN QUERY EXECUTE format(
            $sql$
            WITH folders AS (
                SELECT path_tokens[$1] AS folder
                FROM storage.objects
                WHERE objects.name ILIKE $2 || '%%'
                  AND bucket_id = $3
                  AND array_length(objects.path_tokens, 1) <> $1
                GROUP BY folder
                ORDER BY folder %s
            )
            (SELECT folder AS "name",
                   NULL::uuid AS id,
                   NULL::timestamptz AS updated_at,
                   NULL::timestamptz AS created_at,
                   NULL::timestamptz AS last_accessed_at,
                   NULL::jsonb AS metadata FROM folders)
            UNION ALL
            (SELECT path_tokens[$1] AS "name",
                   id, updated_at, created_at, last_accessed_at, metadata
             FROM storage.objects
             WHERE objects.name ILIKE $2 || '%%'
               AND bucket_id = $3
               AND array_length(objects.path_tokens, 1) = $1
             ORDER BY %I %s)
            LIMIT $4 OFFSET $5
            $sql$, v_sort_order, v_order_by, v_sort_order
        ) USING levels, v_prefix, bucketname, v_limit, offsets;
        RETURN;
    END IF;

    -- ========================================================================
    -- NAME SORTING: Hybrid skip-scan with batch optimization
    -- ========================================================================

    -- Calculate upper bound for prefix filtering
    IF v_prefix_lower = '' THEN
        v_upper_bound := NULL;
    ELSIF right(v_prefix_lower, 1) = v_delimiter THEN
        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(v_delimiter) + 1);
    ELSE
        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(right(v_prefix_lower, 1)) + 1);
    END IF;

    -- Build batch query (dynamic SQL - called infrequently, amortized over many rows)
    IF v_is_asc THEN
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" >= $2 ' ||
                'AND lower(o.name) COLLATE "C" < $3 ORDER BY lower(o.name) COLLATE "C" ASC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" >= $2 ' ||
                'ORDER BY lower(o.name) COLLATE "C" ASC LIMIT $4';
        END IF;
    ELSE
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" < $2 ' ||
                'AND lower(o.name) COLLATE "C" >= $3 ORDER BY lower(o.name) COLLATE "C" DESC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" < $2 ' ||
                'ORDER BY lower(o.name) COLLATE "C" DESC LIMIT $4';
        END IF;
    END IF;

    -- Initialize seek position
    IF v_is_asc THEN
        v_next_seek := v_prefix_lower;
    ELSE
        -- DESC: find the last item in range first (static SQL)
        IF v_upper_bound IS NOT NULL THEN
            SELECT o.name INTO v_peek_name FROM storage.objects o
            WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_prefix_lower AND lower(o.name) COLLATE "C" < v_upper_bound
            ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
        ELSIF v_prefix_lower <> '' THEN
            SELECT o.name INTO v_peek_name FROM storage.objects o
            WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_prefix_lower
            ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
        ELSE
            SELECT o.name INTO v_peek_name FROM storage.objects o
            WHERE o.bucket_id = bucketname
            ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
        END IF;

        IF v_peek_name IS NOT NULL THEN
            v_next_seek := lower(v_peek_name) || v_delimiter;
        ELSE
            RETURN;
        END IF;
    END IF;

    -- ========================================================================
    -- MAIN LOOP: Hybrid peek-then-batch algorithm
    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch
    -- ========================================================================
    LOOP
        EXIT WHEN v_count >= v_limit;

        -- STEP 1: PEEK using STATIC SQL (plan cached, very fast)
        IF v_is_asc THEN
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek AND lower(o.name) COLLATE "C" < v_upper_bound
                ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek
                ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
            END IF;
        ELSE
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek AND lower(o.name) COLLATE "C" >= v_prefix_lower
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            ELSIF v_prefix_lower <> '' THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek AND lower(o.name) COLLATE "C" >= v_prefix_lower
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            END IF;
        END IF;

        EXIT WHEN v_peek_name IS NULL;

        -- STEP 2: Check if this is a FOLDER or FILE
        v_common_prefix := storage.get_common_prefix(lower(v_peek_name), v_prefix_lower, v_delimiter);

        IF v_common_prefix IS NOT NULL THEN
            -- FOLDER: Handle offset, emit if needed, skip to next folder
            IF v_skipped < offsets THEN
                v_skipped := v_skipped + 1;
            ELSE
                name := split_part(rtrim(storage.get_common_prefix(v_peek_name, v_prefix, v_delimiter), v_delimiter), v_delimiter, levels);
                id := NULL;
                updated_at := NULL;
                created_at := NULL;
                last_accessed_at := NULL;
                metadata := NULL;
                RETURN NEXT;
                v_count := v_count + 1;
            END IF;

            -- Advance seek past the folder range
            IF v_is_asc THEN
                v_next_seek := lower(left(v_common_prefix, -1)) || chr(ascii(v_delimiter) + 1);
            ELSE
                v_next_seek := lower(v_common_prefix);
            END IF;
        ELSE
            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)
            -- For ASC: upper_bound is the exclusive upper limit (< condition)
            -- For DESC: prefix_lower is the inclusive lower limit (>= condition)
            FOR v_current IN EXECUTE v_batch_query
                USING bucketname, v_next_seek,
                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix_lower) ELSE v_prefix_lower END, v_file_batch_size
            LOOP
                v_common_prefix := storage.get_common_prefix(lower(v_current.name), v_prefix_lower, v_delimiter);

                IF v_common_prefix IS NOT NULL THEN
                    -- Hit a folder: exit batch, let peek handle it
                    v_next_seek := lower(v_current.name);
                    EXIT;
                END IF;

                -- Handle offset skipping
                IF v_skipped < offsets THEN
                    v_skipped := v_skipped + 1;
                ELSE
                    -- Emit file
                    name := split_part(v_current.name, v_delimiter, levels);
                    id := v_current.id;
                    updated_at := v_current.updated_at;
                    created_at := v_current.created_at;
                    last_accessed_at := v_current.last_accessed_at;
                    metadata := v_current.metadata;
                    RETURN NEXT;
                    v_count := v_count + 1;
                END IF;

                -- Advance seek past this file
                IF v_is_asc THEN
                    v_next_seek := lower(v_current.name) || v_delimiter;
                ELSE
                    v_next_seek := lower(v_current.name);
                END IF;

                EXIT WHEN v_count >= v_limit;
            END LOOP;
        END IF;
    END LOOP;
END;
$_$;


--
-- Name: search_by_timestamp(text, text, integer, integer, text, text, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.search_by_timestamp(p_prefix text, p_bucket_id text, p_limit integer, p_level integer, p_start_after text, p_sort_order text, p_sort_column text, p_sort_column_after text) RETURNS TABLE(key text, name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb)
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
    v_cursor_op text;
    v_query text;
    v_prefix text;
BEGIN
    v_prefix := coalesce(p_prefix, '');

    IF p_sort_order = 'asc' THEN
        v_cursor_op := '>';
    ELSE
        v_cursor_op := '<';
    END IF;

    v_query := format($sql$
        WITH raw_objects AS (
            SELECT
                o.name AS obj_name,
                o.id AS obj_id,
                o.updated_at AS obj_updated_at,
                o.created_at AS obj_created_at,
                o.last_accessed_at AS obj_last_accessed_at,
                o.metadata AS obj_metadata,
                storage.get_common_prefix(o.name, $1, '/') AS common_prefix
            FROM storage.objects o
            WHERE o.bucket_id = $2
              AND o.name COLLATE "C" LIKE $1 || '%%'
        ),
        -- Aggregate common prefixes (folders)
        -- Both created_at and updated_at use MIN(obj_created_at) to match the old prefixes table behavior
        aggregated_prefixes AS (
            SELECT
                rtrim(common_prefix, '/') AS name,
                NULL::uuid AS id,
                MIN(obj_created_at) AS updated_at,
                MIN(obj_created_at) AS created_at,
                NULL::timestamptz AS last_accessed_at,
                NULL::jsonb AS metadata,
                TRUE AS is_prefix
            FROM raw_objects
            WHERE common_prefix IS NOT NULL
            GROUP BY common_prefix
        ),
        leaf_objects AS (
            SELECT
                obj_name AS name,
                obj_id AS id,
                obj_updated_at AS updated_at,
                obj_created_at AS created_at,
                obj_last_accessed_at AS last_accessed_at,
                obj_metadata AS metadata,
                FALSE AS is_prefix
            FROM raw_objects
            WHERE common_prefix IS NULL
        ),
        combined AS (
            SELECT * FROM aggregated_prefixes
            UNION ALL
            SELECT * FROM leaf_objects
        ),
        filtered AS (
            SELECT *
            FROM combined
            WHERE (
                $5 = ''
                OR ROW(
                    date_trunc('milliseconds', %I),
                    name COLLATE "C"
                ) %s ROW(
                    COALESCE(NULLIF($6, '')::timestamptz, 'epoch'::timestamptz),
                    $5
                )
            )
        )
        SELECT
            split_part(name, '/', $3) AS key,
            name,
            id,
            updated_at,
            created_at,
            last_accessed_at,
            metadata
        FROM filtered
        ORDER BY
            COALESCE(date_trunc('milliseconds', %I), 'epoch'::timestamptz) %s,
            name COLLATE "C" %s
        LIMIT $4
    $sql$,
        p_sort_column,
        v_cursor_op,
        p_sort_column,
        p_sort_order,
        p_sort_order
    );

    RETURN QUERY EXECUTE v_query
    USING v_prefix, p_bucket_id, p_level, p_limit, p_start_after, p_sort_column_after;
END;
$_$;


--
-- Name: search_v2(text, text, integer, integer, text, text, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.search_v2(prefix text, bucket_name text, limits integer DEFAULT 100, levels integer DEFAULT 1, start_after text DEFAULT ''::text, sort_order text DEFAULT 'asc'::text, sort_column text DEFAULT 'name'::text, sort_column_after text DEFAULT ''::text) RETURNS TABLE(key text, name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_sort_col text;
    v_sort_ord text;
    v_limit int;
BEGIN
    -- Cap limit to maximum of 1500 records
    v_limit := LEAST(coalesce(limits, 100), 1500);

    -- Validate and normalize sort_order
    v_sort_ord := lower(coalesce(sort_order, 'asc'));
    IF v_sort_ord NOT IN ('asc', 'desc') THEN
        v_sort_ord := 'asc';
    END IF;

    -- Validate and normalize sort_column
    v_sort_col := lower(coalesce(sort_column, 'name'));
    IF v_sort_col NOT IN ('name', 'updated_at', 'created_at') THEN
        v_sort_col := 'name';
    END IF;

    -- Route to appropriate implementation
    IF v_sort_col = 'name' THEN
        -- Use list_objects_with_delimiter for name sorting (most efficient: O(k * log n))
        RETURN QUERY
        SELECT
            split_part(l.name, '/', levels) AS key,
            l.name AS name,
            l.id,
            l.updated_at,
            l.created_at,
            l.last_accessed_at,
            l.metadata
        FROM storage.list_objects_with_delimiter(
            bucket_name,
            coalesce(prefix, ''),
            '/',
            v_limit,
            start_after,
            '',
            v_sort_ord
        ) l;
    ELSE
        -- Use aggregation approach for timestamp sorting
        -- Not efficient for large datasets but supports correct pagination
        RETURN QUERY SELECT * FROM storage.search_by_timestamp(
            prefix, bucket_name, v_limit, levels, start_after,
            v_sort_ord, v_sort_col, sort_column_after
        );
    END IF;
END;
$$;


--
-- Name: update_updated_at_column(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.update_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW; 
END;
$$;


