    medio_pago text
);


--
-- Name: cta_cte_empresa; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.cta_cte_empresa AS
 SELECT cc.id,
    cc.cliente_id,
    cc.tipo,
    cc.monto,
    cc.factura_id,
    cc.cobro_id,
    cc.saldo,
    cc.fecha,
    c.empresa_id
   FROM (public.cta_cte cc
     JOIN public.clientes c ON ((c.id = cc.cliente_id)));


--
-- Name: cuenta_corriente; Type: VIEW; Schema: public; Owner: -
